import { api, getToken, setToken, connectSocket, escapeHtml } from './api.js';
import { HEROES, ROLES, getHeroImg, roleIconMarkup } from './heroes.js';
import { bindDraftRulesForm, renderDraftRulesForm } from './draft-rules-form.js';
import { t } from './i18n.js';

const state = {
  user: null,
  tournaments: [],
  activeId: Number(new URLSearchParams(location.search).get('tournamentId')) || Number(localStorage.getItem('gs_active_tournament_id')) || null,
  active: null,
  socket: null,
  bracketZoom: 1,
  bracketCompact: false,
  hideCompleted: false,
  bracketSearch: '',
  openMatchId: null,
  openTeamId: null,
};

const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
function toast(message,error=false){const el=$('#ops-toast');el.textContent=message;el.classList.toggle('error',error);el.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),4500);}
function formatDate(value){if(!value)return 'Not set';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString();}
function statusLabel(value){return String(value||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}
function can(permission){const list=state.active?.permissions?.permissions||[];return list.includes('*')||list.includes(permission);}
function isBroadcastViewer(){return can('broadcast.control')&&!can('tournament.manage')&&!can('match.manage')&&!can('result.verify');}
function copyText(text,label='Copied.'){navigator.clipboard.writeText(text).then(()=>toast(label)).catch(()=>toast('Copy failed.',true));}
function openExternal(url){if(url)window.open(url,'_blank','noopener,noreferrer');}
async function downloadFile(fileId,fileName='attachment'){try{const response=await fetch(`/api/files/${fileId}`,{credentials:'same-origin'});if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.error||`Download failed (${response.status})`);}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=fileName;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message,true);}}
function chatAttachmentHtml(message){if(!message.file_id||message.deleted_at)return'';const name=escapeHtml(message.file_name||'Attachment');if(String(message.file_mime||'').startsWith('image/'))return `<figure class="ops-chat-image"><img src="/api/files/${Number(message.file_id)}?inline=1" alt="${name}" loading="lazy"><figcaption>${name}</figcaption></figure>`;return `<button type="button" class="ops-file-link" data-file-id="${Number(message.file_id)}" data-file-name="${name}">📎 ${name}</button>`;}

function showAuth(){ $('#auth-view').classList.remove('hidden');$('#dashboard-view').classList.add('hidden');$('#btn-logout').classList.add('hidden');window.GSGlobalMenu?.refresh(); }
function showDashboard(){ $('#auth-view').classList.add('hidden');$('#dashboard-view').classList.remove('hidden');$('#btn-logout').classList.add('hidden');window.GSGlobalMenu?.refresh();$('#btn-dev-console').classList.toggle('hidden',state.user.role!=='admin'); }

async function bootstrap(){bindStaticEvents();if(!getToken())return showAuth();try{state.user=(await api('/api/auth/me')).user;showDashboard();connectRealtime();await loadTournaments();}catch(error){setToken('');showAuth();toast(error.message,true);}}
function connectRealtime(){state.socket?.disconnect();state.socket=connectSocket();if(!state.socket)return;const refresh=payload=>{if(Number(payload?.tournamentId)===state.activeId)loadActiveTournament({quiet:true});};state.socket.on('bracket:updated',refresh);state.socket.on('match:updated',match=>{if(Number(match?.tournament_id)===state.activeId)loadActiveTournament({quiet:true});});state.socket.on('match:checkin',async payload=>{if(Number(payload?.tournamentId)!==state.activeId)return;const openMatchId=state.openMatchId;await loadActiveTournament({quiet:true});if(openMatchId===Number(payload?.matchId))openMatchModal(openMatchId);});state.socket.on('match:chat',payload=>{if(Number(payload?.matchId)===state.openMatchId&&payload.message)appendChat(payload.message);else if(state.activeId)updateUnreadBadge(Number(payload?.matchId));});}

function bindStaticEvents(){
  $('#login-form').addEventListener('submit',async event=>{event.preventDefault();try{const payload=await api('/api/auth/login',{method:'POST',body:{identity:$('#login-identity').value,password:$('#login-password').value}});setToken('cookie-session');state.user=payload.user;showDashboard();connectRealtime();await loadTournaments();}catch(error){toast(error.message,true);}});
  $('#btn-logout').addEventListener('click',()=>{setToken('');state.socket?.disconnect();state.user=null;showAuth();});
  $('#btn-refresh').addEventListener('click',()=>loadActiveTournament());
  $('#btn-dev-console').addEventListener('click',openDevConsole);
  $('#close-dev-console').addEventListener('click',closeDevConsole);
  $('#dev-console-modal').addEventListener('click',event=>{if(event.target.id==='dev-console-modal')closeDevConsole();});
  $('#close-team-modal').addEventListener('click',closeTeamModal);
  $('#team-modal').addEventListener('click',event=>{if(event.target.id==='team-modal')closeTeamModal();});
  $('#close-match-modal').addEventListener('click',closeMatchModal);
  $('#match-modal').addEventListener('click',event=>{if(event.target.id==='match-modal')closeMatchModal();});
  document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;if(!$('#team-modal').classList.contains('hidden'))closeTeamModal();else if(!$('#match-modal').classList.contains('hidden'))closeMatchModal();});
  $('#ops-tabs').addEventListener('click',event=>{const button=event.target.closest('[data-tab]');if(!button)return;$$('#ops-tabs button').forEach(item=>item.classList.toggle('active',item===button));$$('.ops-tab-panel').forEach(item=>item.classList.add('hidden'));$(`#tab-${button.dataset.tab}`).classList.remove('hidden');});
}

async function loadTournaments(){const payload=await api('/api/tournaments');state.tournaments=payload.tournaments;renderTournamentList();if(state.activeId&&state.tournaments.some(item=>item.id===state.activeId))await loadActiveTournament();else if(state.tournaments[0]){state.activeId=state.tournaments[0].id;await loadActiveTournament();}else{state.activeId=null;state.active=null;localStorage.removeItem('gs_active_tournament_id');$('#no-tournament').classList.remove('hidden');$('#tournament-workspace').classList.add('hidden');}}
function renderTournamentList(){$('#tournament-list').innerHTML=state.tournaments.length?state.tournaments.map(t=>`<div class="ops-list-item ${t.id===state.activeId?'active':''}" data-id="${t.id}"><div class="ops-list-name">${escapeHtml(t.name)}</div><div class="ops-list-meta">${escapeHtml(t.source_platform||'manual')} · ${escapeHtml(t.status)} · ${escapeHtml(t.timezone)}${t.unverified?' · SOURCE UNVERIFIED':''}</div></div>`).join(''):'<div class="ops-list-meta" style="padding:12px;line-height:1.6">No tournaments yet.<br><a href="/host-apply.html">Import one from start.gg, Tonamel or Challonge.</a></div>';$$('.ops-list-item').forEach(item=>item.addEventListener('click',async()=>{state.activeId=Number(item.dataset.id);localStorage.setItem('gs_active_tournament_id',state.activeId);renderTournamentList();await loadActiveTournament();}));}
async function loadActiveTournament({quiet=false}={}){if(!state.activeId)return;try{state.active=await api(`/api/tournaments/${state.activeId}`);localStorage.setItem('gs_active_tournament_id',state.activeId);$('#no-tournament').classList.add('hidden');$('#tournament-workspace').classList.remove('hidden');$('#tournament-name').textContent=state.active.tournament.name;$('#tournament-status').textContent=state.active.tournament.status;state.socket?.emit('tournament:join',{tournamentId:state.activeId});renderAll();}catch(error){if(!quiet)toast(error.message,true);}}
function renderAll(){renderOverview();renderTeams();renderBracket();renderRules();renderStaff();renderStartgg();renderAudit();applyRoleView();}
function applyRoleView(){
  const broadcasterOnly=isBroadcastViewer();
  $$('#ops-tabs [data-tab]').forEach(button=>button.classList.toggle('hidden',broadcasterOnly&&!['overview','bracket'].includes(button.dataset.tab)));
  if(broadcasterOnly){
    $('#tab-overview').querySelectorAll('button:not(#copy-public-link),input,select,textarea').forEach(control=>control.remove());
  }
}

function renderOverview(){const {tournament,teams,matches,preflight}=state.active;const completed=matches.filter(m=>m.result_status==='final').length;const active=matches.find(m=>['drafting','playing','paused','technical_issue'].includes(m.match_status));const publicUrl=`${location.origin}/public.html?slug=${encodeURIComponent(tournament.slug)}`;const bracketReady=matches.length>0;const tournamentStatus=String(tournament.status||'').toLowerCase();const started=['ongoing','running','live'].includes(tournamentStatus);const terminal=['completed','cancelled','archived'].includes(tournamentStatus);const draftReady=matches.some(match=>Boolean(match.draft_room_ready));$('#tab-overview').innerHTML=`
  ${tournament.unverified?`<div class="ops-notice warning"><div><b>External tournament source is not verified.</b><div>Automatic metadata could not be read. Check the source link, tournament name and description, then confirm them manually.</div></div>${can('tournament.manage')?'<button type="button" class="btn btn-primary btn-sm" id="verify-tournament-source">REVIEW & CONFIRM</button>':''}</div>`:''}
  <div class="ops-stat-grid"><div class="ops-stat"><div class="ops-stat-value">${teams.length}</div><div class="ops-stat-label">Teams</div></div><div class="ops-stat"><div class="ops-stat-value">${matches.length}</div><div class="ops-stat-label">Matches</div></div><div class="ops-stat"><div class="ops-stat-value">${completed}</div><div class="ops-stat-label">Final Results</div></div><div class="ops-stat"><div class="ops-stat-value">${preflight.ok?'READY':'CHECK'}</div><div class="ops-stat-label">Preflight</div></div></div>
  <div class="ops-section ops-start-guide"><div class="ops-section-header"><div><h3>Start Tournament Checklist</h3><div class="ops-list-meta">Follow these steps in order. Starting opens check-in for every currently playable match.</div></div>${can('tournament.manage')&&!started&&!terminal?`<button class="btn btn-primary" id="start-tournament" ${preflight.ok&&bracketReady?'':'disabled'}>START TOURNAMENT</button>`:started?'<span class="ops-result-lock">TOURNAMENT STARTED</span>':terminal?`<span class="ops-result-lock">${escapeHtml(statusLabel(tournamentStatus))}</span>`:''}</div><div class="ops-start-steps"><button type="button" data-open-tab="overview" class="${preflight.ok?'done':'active'}"><b>1</b><span>Run preflight<small>${preflight.ok?'Ready':'Resolve blockers'}</small></span></button><i></i><button type="button" data-open-tab="bracket" class="${bracketReady?'done':preflight.ok?'active':'waiting'}"><b>2</b><span>Generate bracket<small>${bracketReady?`${matches.length} matches created`:'Create match structure'}</small></span></button><i></i><button type="button" data-open-tab="overview" class="${started||terminal?'done':bracketReady?'active':'waiting'}"><b>3</b><span>Start tournament<small>${started?'Check-in opened':terminal?'Tournament finished':'Host action required'}</small></span></button><i></i><button type="button" data-open-tab="bracket" class="${draftReady||terminal?'done':started?'active':'waiting'}"><b>4</b><span>Open first Draft Room<small>${draftReady?'Team links ready':terminal?'Operations completed':'Click the playable match'}</small></span></button></div></div>
  <div class="ops-section"><div class="ops-panel-header ops-section-header"><div><h3>Tournament Preflight</h3><div class="ops-list-meta">Captain accounts, roster readiness, unique seeds and constraint conflicts.</div></div><button class="btn btn-primary btn-sm" id="run-preflight">RUN CHECK</button></div>${renderPreflight(preflight)}</div>
  <div class="ops-section"><h3>Public Bracket & External Stream</h3><div class="ops-link-row"><b>PUBLIC BRACKET</b><input readonly value="${escapeHtml(publicUrl)}"><a class="btn btn-ghost btn-xs" href="${escapeHtml(publicUrl)}" target="_blank" rel="noopener">OPEN</a><button class="btn btn-ghost btn-xs" id="copy-public-link">COPY</button></div>${tournament.public_stream_url?`<div class="ops-link-row"><b>${escapeHtml(tournament.public_stream_platform||'STREAM')}</b><input readonly value="${escapeHtml(tournament.public_stream_url)}"><a class="btn btn-primary btn-xs" href="${escapeHtml(tournament.public_stream_url)}" target="_blank" rel="noopener">OPEN EXTERNAL ↗</a></div>`:'<div class="ops-list-meta" style="margin-top:10px">No Twitch/YouTube link set. Video is never embedded on this website.</div>'}</div>
  <div class="ops-section"><h3>Live Operations</h3>${active?`<div>${escapeHtml(active.team_a_name||'TBD')} vs ${escapeHtml(active.team_b_name||'TBD')} · ${escapeHtml(statusLabel(active.match_status))}</div>`:'<div class="ops-list-meta">No match is marked live on the website.</div>'}</div>
  <div class="ops-section"><h3>System Boundary</h3><div class="ops-list-meta" style="line-height:1.7">Host and referee controls affect website data, draft timer/state and OBS overlays only. They do not pause, restart or control the actual game. A future official game API may be used read-only.</div></div>`;
  $('#copy-public-link').addEventListener('click',()=>copyText(publicUrl,'Public bracket link copied.'));$('#run-preflight').addEventListener('click',async()=>{const check=await api(`/api/tournaments/${state.activeId}/preflight`);state.active.preflight=check;renderOverview();toast(check.ok?'Preflight passed.':`${check.blockers.length} blocker(s) found.`,!check.ok);});$('#start-tournament')?.addEventListener('click',async()=>{if(!confirm('Start this tournament and open check-in for every playable match?'))return;try{await api(`/api/tournaments/${state.activeId}/start`,{method:'POST',body:{}});toast('Tournament started. Open the first match and create its Draft Room.');await loadActiveTournament();}catch(error){toast(error.message,true);}});$$('[data-open-tab]').forEach(button=>button.addEventListener('click',()=>{const tab=button.dataset.openTab;const target=$(`#ops-tabs [data-tab="${tab}"]`);if(target&&!target.classList.contains('hidden'))target.click();}));$('#verify-tournament-source')?.addEventListener('click',async()=>{const name=prompt('Confirm or correct the tournament name:',tournament.name);if(name===null)return;const description=prompt('Confirm or correct the tournament description:',tournament.description||'');if(description===null)return;try{await api(`/api/tournaments/${state.activeId}/verify-source`,{method:'POST',body:{name,description}});toast('External source details confirmed by Host.');await loadTournaments();}catch(error){toast(error.message,true);}});}
function renderPreflight(check){return `<div class="ops-preflight ${check.ok?'ok':'has-errors'}"><div class="ops-preflight-title">${check.ok?'✓ Ready to generate':'⚠ Action required'}</div>${check.blockers.length?`<div class="ops-preflight-list"><b>Blockers</b>${check.blockers.map(item=>`<div>• ${escapeHtml(item)}</div>`).join('')}</div>`:''}${check.warnings.length?`<div class="ops-preflight-list warning"><b>Warnings</b>${check.warnings.map(item=>`<div>• ${escapeHtml(item)}</div>`).join('')}</div>`:''}</div>`;}

function renderTeams(){const teams=state.active.teams;const joinRequests=(state.active.joinRequests||[]).filter(item=>item.status==='pending');$('#tab-teams').innerHTML=`
  ${renderJoinRequests(joinRequests,teams)}
  <div class="ops-section"><h3>Add Manual Team</h3><form id="add-team-form" class="ops-form-card"><label>Team name<input id="team-name" required></label><label>Tag <span class="ops-field-hint">optional</span><input id="team-tag" maxlength="8" placeholder="Auto-generated"></label><label>Region<input id="team-region" placeholder="Asia / Japan / SEA"></label><button class="btn btn-primary" type="submit">ADD TEAM</button></form></div>
  <div class="ops-section"><div class="ops-panel-header ops-section-header"><div><h3>Teams & Drag-and-Drop Seeding</h3><div class="ops-list-meta">Kéo bằng tay cầm ⋮⋮ hoặc dùng nút ↑ ↓. Click vào thẻ đội để mở cửa sổ chi tiết và chỉnh sửa.</div></div><div class="ops-toolbar"><button class="btn btn-ghost btn-sm" id="randomize-seeds">🎲 RANDOMIZE UNLOCKED</button><button class="btn btn-ghost btn-sm" id="undo-seeds">↶ UNDO</button><button class="btn btn-primary btn-sm" id="save-seeds">SAVE SEED ORDER</button></div></div>
  <div class="ops-seed-list" id="ops-seed-list">${teams.length?teams.map(team=>seedRow(team)).join(''):'<div class="ops-list-meta">No teams imported or created.</div>'}</div></div>`;
  $('#add-team-form').addEventListener('submit',async event=>{event.preventDefault();try{await api(`/api/tournaments/${state.activeId}/teams`,{method:'POST',body:{name:$('#team-name').value,tag:$('#team-tag').value,region:$('#team-region').value}});toast('Team created. Link a Captain account before generating the bracket.');await loadActiveTournament();}catch(error){toast(error.message,true);}});
  bindJoinRequestActions();
  bindSeedDrag();
  $$('.ops-seed-row').forEach(row=>{
    const openDetails=()=>openTeamModal(Number(row.dataset.teamId));
    row.addEventListener('click',event=>{
      if(event.target.closest('.ops-seed-reorder,.ops-lock-seed,input,button,select,textarea,a'))return;
      openDetails();
    });
    row.addEventListener('keydown',event=>{
      if(event.target!==row||!['Enter',' '].includes(event.key))return;
      event.preventDefault();
      openDetails();
    });
  });
  $$('.seed-move').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();moveSeedRow(button.closest('.ops-seed-row'),button.dataset.direction);}));
  $$('.ops-lock-seed').forEach(label=>{
    label.addEventListener('click',event=>event.stopPropagation());
    label.addEventListener('pointerdown',event=>event.stopPropagation());
  });
  $('#save-seeds').addEventListener('click',saveTeamsAndSeeds);$('#randomize-seeds').addEventListener('click',async()=>{try{await saveTeamsAndSeeds({reload:false});await api(`/api/tournaments/${state.activeId}/seeding/randomize`,{method:'POST'});toast('Unlocked seeds randomized. Locked positions were preserved.');await loadActiveTournament();}catch(error){toast(error.message,true);}});$('#undo-seeds').addEventListener('click',async()=>{try{await api(`/api/tournaments/${state.activeId}/seeding/undo`,{method:'POST'});toast('Previous seeding snapshot restored.');await loadActiveTournament();}catch(error){toast(error.message,true);}});
}
function renderJoinRequests(requests,teams){
  if(!requests.length)return `<div class="ops-section"><div class="ops-section-header"><div><h3>Player & Captain Join Requests</h3><div class="ops-list-meta">No pending account-link requests. Players can use the JOIN / LINK ACCOUNT button on the public event page.</div></div></div></div>`;
  return `<div class="ops-section"><div class="ops-section-header"><div><h3>Player & Captain Join Requests</h3><div class="ops-list-meta">Confirm that the account matches the entrant or roster shown on the external tournament platform.</div></div><span class="ops-status-pill status-pending">${requests.length} PENDING</span></div><div class="ops-join-request-list">${requests.map(request=>{const selected=Number(request.team_id||0);const teamOptions=teams.filter(team=>!['withdrawn','disqualified'].includes(team.team_status)).map(team=>`<option value="${team.id}" ${Number(team.id)===selected?'selected':''}>${escapeHtml(team.name)} [${escapeHtml(team.tag||'—')}]</option>`).join('');return `<article class="ops-join-request-card" data-request-id="${request.id}"><div class="ops-join-request-main"><span>${escapeHtml(statusLabel(request.requested_role))}</span><h4>${escapeHtml(request.display_name)} <small>@${escapeHtml(request.username)}</small></h4><p><b>External gamer tag:</b> ${escapeHtml(request.gamer_tag||request.selected_member_tag||'Not provided')}</p><p><b>Requested team:</b> ${escapeHtml(request.team_name||request.requested_team_name||'Not synced')}</p>${request.selected_member_name?`<p><b>Roster slot:</b> ${escapeHtml(request.selected_member_name)}</p>`:''}${request.message?`<blockquote>${escapeHtml(request.message)}</blockquote>`:''}</div><div class="ops-join-request-review"><label>Link to team<select class="join-review-team"><option value="">Select team</option>${teamOptions}${request.requested_team_name?`<option value="__create__">Create “${escapeHtml(request.requested_team_name)}”</option>`:''}</select></label><div><button type="button" class="btn btn-primary btn-sm approve-join-request">APPROVE</button><button type="button" class="btn btn-danger btn-sm reject-join-request">REJECT</button></div></div></article>`;}).join('')}</div></div>`;
}
function bindJoinRequestActions(){
  $$('.approve-join-request').forEach(button=>button.addEventListener('click',async()=>{const card=button.closest('.ops-join-request-card'),selection=card.querySelector('.join-review-team').value;if(!selection)return toast('Select the team before approving.',true);try{await api(`/api/tournaments/${state.activeId}/join-requests/${card.dataset.requestId}/review`,{method:'POST',body:{decision:'approve',teamId:selection==='__create__'?null:Number(selection),createTeam:selection==='__create__'}});toast('Account linked to the tournament team.');await loadActiveTournament();}catch(error){toast(error.message,true);}}));
  $$('.reject-join-request').forEach(button=>button.addEventListener('click',async()=>{const card=button.closest('.ops-join-request-card');const reviewNote=prompt('Reason shown to the player (optional):')||'';try{await api(`/api/tournaments/${state.activeId}/join-requests/${card.dataset.requestId}/review`,{method:'POST',body:{decision:'reject',reviewNote}});toast('Join request rejected.');await loadActiveTournament();}catch(error){toast(error.message,true);}}));
}

function seedRow(team){
  const terminal=['withdrawn','disqualified'].includes(team.team_status);
  const captain=team.captain_user_id
    ?`Captain: ${escapeHtml(team.captain_display_name||team.captain_username)}`
    :'Captain account missing';

  return `<div class="ops-seed-row ${terminal?'is-inactive':''}" data-team-id="${team.id}" draggable="${!terminal}" tabindex="0" aria-label="Open details for ${escapeHtml(team.name)}">
    <div class="ops-seed-reorder" aria-label="Seed order controls">
      <div class="ops-drag-handle" title="Drag to change seed" aria-label="Drag team">⋮⋮</div>
      <button type="button" class="btn btn-ghost btn-xs seed-move" data-direction="up" ${terminal?'disabled':''} title="Move team up" aria-label="Move team up">↑</button>
      <button type="button" class="btn btn-ghost btn-xs seed-move" data-direction="down" ${terminal?'disabled':''} title="Move team down" aria-label="Move team down">↓</button>
    </div>
    <div class="ops-seed-number">${terminal?'—':team.seed||'?'}</div>
    <div class="ops-seed-team-summary" title="Click anywhere on this team card to open details">
      <span class="ops-seed-team-title"><strong>${escapeHtml(team.name)}</strong><span class="ops-team-tag-badge">${escapeHtml(team.tag||'—')}</span></span>
      <span class="ops-team-subline"><span class="ops-source-pill">${escapeHtml(team.source)}</span><span>${team.members.length} members</span><span>${escapeHtml(team.region||'No region')}</span><span class="captain-state ${team.captain_user_id?'ok':''}">${captain}</span></span>
    </div>
    <div class="ops-seed-constraint"><span>PROTECTION</span><b>${escapeHtml(team.protected_seed_group||'None')}</b><small>${team.seeding_note?escapeHtml(team.seeding_note):'No seeding note'}</small></div>
    <label class="ops-lock-seed ${terminal?'is-disabled':''}" title="Keep this team at the exact seed when randomizing">
      <input class="team-seed-lock" type="checkbox" ${team.seed_locked?'checked':''} ${terminal?'disabled':''}>
      <span>LOCK SEED</span>
    </label>
    <span class="ops-status-pill status-${escapeHtml(team.team_status)}">${escapeHtml(statusLabel(team.team_status))}</span>
    <input type="hidden" class="team-name-input" value="${escapeHtml(team.name)}">
    <input type="hidden" class="team-tag-input" value="${escapeHtml(team.tag)}">
    <input type="hidden" class="team-region-input" value="${escapeHtml(team.region||'')}">
    <input type="hidden" class="team-protected-input" value="${escapeHtml(team.protected_seed_group||'')}">
    <textarea class="team-seeding-note hidden">${escapeHtml(team.seeding_note||'')}</textarea>
  </div>`;
}
function refreshSeedNumbers(){let seed=1;$('#ops-seed-list')?.querySelectorAll('.ops-seed-row').forEach(row=>row.querySelector('.ops-seed-number').textContent=row.classList.contains('is-inactive')?'—':seed++);}
function moveSeedRow(row,direction){if(!row||row.classList.contains('is-inactive'))return;const sibling=direction==='up'?row.previousElementSibling:row.nextElementSibling;if(!sibling||sibling.classList.contains('is-inactive'))return;const list=row.parentElement;if(direction==='up')list.insertBefore(row,sibling);else list.insertBefore(sibling,row);refreshSeedNumbers();}
function bindSeedDrag(){const list=$('#ops-seed-list');let dragging=null;let armed=false;list.querySelectorAll('.ops-seed-row[draggable="true"]').forEach(row=>{const handle=row.querySelector('.ops-drag-handle');handle.addEventListener('pointerdown',()=>{armed=true;});handle.addEventListener('pointerup',()=>{armed=false;});handle.addEventListener('pointercancel',()=>{armed=false;});row.addEventListener('dragstart',event=>{if(!armed){event.preventDefault();return;}dragging=row;row.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',row.dataset.teamId);});row.addEventListener('dragend',()=>{row.classList.remove('dragging');dragging=null;armed=false;});row.addEventListener('dragover',event=>{event.preventDefault();if(!dragging||dragging===row||row.classList.contains('is-inactive'))return;const rect=row.getBoundingClientRect();list.insertBefore(dragging,event.clientY>rect.top+rect.height/2?row.nextSibling:row);refreshSeedNumbers();});});}
async function saveTeamsAndSeeds({reload=true}={}){const list=$('#ops-seed-list');const rows=[...list.querySelectorAll('.ops-seed-row')];const activeRows=rows.filter(row=>!row.classList.contains('is-inactive'));await api(`/api/tournaments/${state.activeId}/seeding`,{method:'PUT',body:{seeds:activeRows.map((row,index)=>({teamId:Number(row.dataset.teamId),seed:index+1,seedLocked:row.querySelector('.team-seed-lock').checked,protectedSeedGroup:row.querySelector('.team-protected-input').value.trim(),region:row.querySelector('.team-region-input').value.trim(),seedingNote:row.querySelector('.team-seeding-note').value.trim()}))}});toast(`Saved ${activeRows.length} seed positions.`);if(reload)await loadActiveTournament();}
function closeTeamModal(){state.openTeamId=null;$('#team-modal').classList.add('hidden');$('#team-modal-body').innerHTML='';}
async function openTeamModal(teamId){const team=state.active.teams.find(item=>item.id===teamId);if(!team)return;state.openTeamId=teamId;$('#team-modal').classList.remove('hidden');$('#team-modal-title').textContent=team.name;$('#team-modal-status').textContent=`Seed ${team.seed||'—'} · ${statusLabel(team.team_status)}`;renderTeamModal(team);}
function renderTeamModal(team){const terminal=['withdrawn','disqualified'].includes(team.team_status);const effectiveRosterLock=team.roster_locked_at||state.active.tournament.roster_lock_at;const rosterLocked=Boolean(effectiveRosterLock&&Date.parse(effectiveRosterLock)<=Date.now());$('#team-modal-body').innerHTML=`<div class="ops-team-modal-grid"><section class="ops-team-editor"><form id="team-details-form" class="ops-settings-grid"><label>Team name<input id="team-detail-name" value="${escapeHtml(team.name)}" required ${terminal?'disabled':''}></label><label>Tag<input id="team-detail-tag" maxlength="8" value="${escapeHtml(team.tag||'')}" placeholder="Auto-generated" ${terminal?'disabled':''}></label><label>Region<input id="team-detail-region" value="${escapeHtml(team.region||'')}" ${terminal?'disabled':''}></label><label>Protected group<input id="team-detail-protect" value="${escapeHtml(team.protected_seed_group||'')}" placeholder="Example: Top 4" ${terminal?'disabled':''}></label><label class="ops-check"><input id="team-detail-lock" type="checkbox" ${team.seed_locked?'checked':''} ${terminal?'disabled':''}> Lock exact seed</label><label>Roster lock<input value="${escapeHtml(team.roster_locked_at||state.active.tournament.roster_lock_at||'Not set')}" disabled></label><label class="ops-span-2">Seeding note / reason<textarea id="team-detail-note" rows="3" ${terminal?'disabled':''}>${escapeHtml(team.seeding_note||'')}</textarea></label>${!terminal?'<button class="btn btn-primary ops-span-2">SAVE TEAM DETAILS</button>':''}</form><div class="ops-captain-panel"><div><b>CAPTAIN ACCOUNT</b><div class="ops-list-meta">${team.captain_user_id?`Linked to ${escapeHtml(team.captain_display_name||team.captain_username)}`:'No Captain account is linked. The team cannot become Ready.'}</div></div>${!terminal?`<form id="assign-captain-form" class="ops-inline-action"><input id="assign-captain-identity" placeholder="Existing username" required><button class="btn btn-primary btn-sm">ASSIGN</button></form><form id="invite-captain-form" class="ops-inline-action"><input id="invite-captain-identity" placeholder="Username to invite" required><button class="btn btn-ghost btn-sm">COPY INVITE LINK</button></form>`:''}</div></section><section class="ops-roster-panel"><div class="ops-panel-header ops-section-header"><div><h3>Roster</h3><div class="ops-list-meta">${team.members.length} member(s)${rosterLocked?' · Roster locked':''}</div></div></div><div class="ops-roster-editor-list">${team.members.length?team.members.map(member=>memberEditorRow(member,rosterLocked||terminal)).join(''):'<div class="ops-list-meta">No roster members yet.</div>'}</div>${!rosterLocked&&!terminal?`<form id="add-member-form" class="ops-add-member-form"><input id="new-member-name" placeholder="Display name" required><input id="new-member-tag" placeholder="In-game tag"><input id="new-member-game-id" placeholder="Game ID"><select id="new-member-role"><option value="player">Player</option><option value="substitute">Substitute</option><option value="coach">Coach</option></select><button class="btn btn-primary btn-sm">+ ADD MEMBER</button></form>`:''}</section></div>${!terminal?`<div class="ops-danger-zone"><div><b>TEAM STATUS ACTIONS</b><div class="ops-list-meta">Withdrawal is voluntary. Disqualification is an organizer penalty.</div></div><button class="btn btn-ghost btn-sm team-terminal-modal" data-status="withdrawn">MARK WITHDRAWN</button><button class="btn btn-danger btn-sm team-terminal-modal" data-status="disqualified">DISQUALIFY</button></div>`:''}`;
  $('#team-details-form')?.addEventListener('submit',event=>saveTeamDetails(event,team));
  $('#assign-captain-form')?.addEventListener('submit',event=>assignCaptainFromModal(event,team));
  $('#invite-captain-form')?.addEventListener('submit',event=>inviteCaptainFromModal(event,team));
  $('#add-member-form')?.addEventListener('submit',event=>addMemberFromModal(event,team));
  $$('.member-edit-form').forEach(form=>form.addEventListener('submit',event=>saveMember(event,team)));
  $$('.delete-member').forEach(button=>button.addEventListener('click',()=>deleteMember(team,Number(button.dataset.memberId),button.dataset.captain==='true')));
  $$('.team-terminal-modal').forEach(button=>button.addEventListener('click',()=>setTeamTerminalFromModal(team,button.dataset.status)));
}
function memberEditorRow(member,disabled){return `<form class="member-edit-form" data-member-id="${member.id}"><input class="member-display-name" value="${escapeHtml(member.display_name)}" placeholder="Display name" ${disabled?'disabled':''}><input class="member-gamer-tag" value="${escapeHtml(member.gamer_tag||'')}" placeholder="In-game tag" ${disabled?'disabled':''}><input class="member-game-id" value="${escapeHtml(member.game_id||'')}" placeholder="Game ID" ${disabled?'disabled':''}><select class="member-role" ${disabled||member.is_captain?'disabled':''}><option value="player" ${member.member_role==='player'?'selected':''}>Player</option><option value="substitute" ${member.member_role==='substitute'||member.is_substitute?'selected':''}>Substitute</option><option value="coach" ${member.member_role==='coach'?'selected':''}>Coach</option><option value="captain" ${member.is_captain?'selected':''}>Captain</option></select><span class="ops-member-flags">${member.is_captain?'★ CAPTAIN':''}${member.user_id?' · ACCOUNT':''}</span>${!disabled?`<button class="btn btn-ghost btn-xs">SAVE</button><button type="button" class="btn btn-danger btn-xs delete-member" data-member-id="${member.id}" data-captain="${Boolean(member.is_captain)}" ${member.is_captain?'disabled title="Transfer Captain before removing"':''}>REMOVE</button>`:''}</form>`;}
async function reloadAndReopenTeam(teamId,message){if(message)toast(message);await loadActiveTournament();openTeamModal(teamId);}
async function saveTeamDetails(event,team){event.preventDefault();try{await api(`/api/tournaments/${state.activeId}/teams/${team.id}`,{method:'PATCH',body:{name:$('#team-detail-name').value.trim(),tag:$('#team-detail-tag').value.trim(),region:$('#team-detail-region').value.trim(),protectedSeedGroup:$('#team-detail-protect').value.trim(),seedingNote:$('#team-detail-note').value.trim(),seedLocked:$('#team-detail-lock').checked}});await reloadAndReopenTeam(team.id,'Team details saved.');}catch(error){toast(error.message,true);}}
async function assignCaptainFromModal(event,team){event.preventDefault();try{await api(`/api/tournaments/${state.activeId}/teams/${team.id}/captain/assign`,{method:'POST',body:{identity:$('#assign-captain-identity').value.trim()}});await reloadAndReopenTeam(team.id,'Captain account assigned.');}catch(error){toast(error.message,true);}}
async function inviteCaptainFromModal(event,team){event.preventDefault();try{const payload=await api(`/api/tournaments/${state.activeId}/teams/${team.id}/captain/invite`,{method:'POST',body:{identity:$('#invite-captain-identity').value.trim()}});copyText(payload.inviteLink,'Captain invitation link copied.');}catch(error){toast(error.message,true);}}
async function addMemberFromModal(event,team){event.preventDefault();try{const role=$('#new-member-role').value;await api(`/api/tournaments/${state.activeId}/teams/${team.id}/members`,{method:'POST',body:{displayName:$('#new-member-name').value.trim(),gamerTag:$('#new-member-tag').value.trim(),gameId:$('#new-member-game-id').value.trim(),memberRole:role,isSubstitute:role==='substitute'}});await reloadAndReopenTeam(team.id,'Roster member added.');}catch(error){toast(error.message,true);}}
async function saveMember(event,team){event.preventDefault();const form=event.currentTarget;try{const role=form.querySelector('.member-role').value;await api(`/api/tournaments/${state.activeId}/teams/${team.id}/members/${form.dataset.memberId}`,{method:'PATCH',body:{displayName:form.querySelector('.member-display-name').value.trim(),gamerTag:form.querySelector('.member-gamer-tag').value.trim(),gameId:form.querySelector('.member-game-id').value.trim(),memberRole:role,isSubstitute:role==='substitute'}});await reloadAndReopenTeam(team.id,'Member updated.');}catch(error){toast(error.message,true);}}
async function deleteMember(team,memberId,isCaptain){if(isCaptain)return toast('Transfer the Captain role before removing this member.',true);if(!confirm('Remove this member from the roster?'))return;try{await api(`/api/tournaments/${state.activeId}/teams/${team.id}/members/${memberId}`,{method:'DELETE'});await reloadAndReopenTeam(team.id,'Member removed.');}catch(error){toast(error.message,true);}}
async function setTeamTerminalFromModal(team,status){const reason=prompt(`${status==='withdrawn'?'Withdrawal':'Disqualification'} reason:`);if(!reason)return;if(!confirm(`Mark ${team.name} as ${status}? Current and future unplayed matches may become walkovers.`))return;try{await api(`/api/tournaments/${state.activeId}/teams/${team.id}/terminal`,{method:'POST',body:{teamStatus:status,reason}});closeTeamModal();toast(`Team marked ${status}.`);await loadActiveTournament();}catch(error){toast(error.message,true);}}

function bracketHelpPanel(structure){
  const groupMode=structure==='groups-playoffs';
  return `<section class="ops-bracket-guide" aria-label="Bracket setup guide">
    <div class="ops-bracket-guide-heading"><div><b>HOW TO USE THIS PAGE</b><span>Follow these three steps. You do not need to understand bracket software.</span></div><span class="ops-bracket-mode-badge">${groupMode?'GROUPS + PLAYOFFS':'SINGLE ELIMINATION'}</span></div>
    <div class="ops-bracket-guide-steps">
      <article><i>1</i><div><b>Choose the format</b><span>${groupMode?'Teams first play inside small groups. The best teams from each group continue to the playoff bracket.':'A team is eliminated after losing one series. The last remaining team is champion.'}</span></div></article>
      <article><i>2</i><div><b>Check the options, then generate</b><span>${groupMode?'“Groups” is the number of pools. “Qualify per group” is how many teams advance from each pool. “Double round robin” means every pair plays twice.':'“Knockout BO” sets the default Best-of for generated matches. Seeds decide the first-round positions.'}</span></div></article>
      <article><i>3</i><div><b>Open a match to operate it</b><span>Click anywhere on a match card to set staff, open the Draft Room, manage chat, or record results. Click only a team name to edit that team.</span></div></article>
    </div>
    ${groupMode?'<div class="ops-bracket-warning"><b>About GENERATE EARLY:</b> It creates playoffs from the standings visible right now, even when group matches are unfinished. Use it only when the organizer intentionally freezes those standings.</div>':''}
  </section>`;
}

function renderBracket(){const matches=state.active.matches;const groupMatches=matches.filter(m=>m.stage==='group');const playoffMatches=matches.filter(m=>m.stage!=='group');const rounds=[...new Set(playoffMatches.map(m=>m.round_no))].sort((a,b)=>a-b);const rules=state.active.tournament.rules||{};const structure=groupMatches.length?'groups-playoffs':(rules.structure||'single');const cardHeight=state.bracketCompact?104:136;const baseGap=state.bracketCompact?14:22;const slot=cardHeight+baseGap;$('#tab-bracket').innerHTML=`
  <div class="ops-section ops-bracket-controls"><div class="ops-panel-header ops-section-header"><div><h3>Generate & Control Tournament Structure</h3><div class="ops-list-meta">The bracket keeps a clean tournament-tree layout. Drag the empty canvas to pan; click a team for Team Details or click the match card for Match Operations.</div></div><select id="bracket-structure"><option value="single" ${structure==='single'?'selected':''}>Single Elimination</option><option value="groups-playoffs" ${structure==='groups-playoffs'?'selected':''}>Group Stage + Playoffs</option></select></div>
  ${bracketHelpPanel(structure)}
  <div id="single-generator" class="ops-generator-row" ${structure==='groups-playoffs'?'hidden':''}><label>Knockout BO<span class="ops-field-help">How many games decide each knockout series.</span><select id="bracket-bo">${[1,3,5,7].map(v=>`<option value="${v}" ${Number(rules.playoffBestOf||3)===v?'selected':''}>BO${v}</option>`).join('')}</select></label><button class="btn btn-primary btn-sm" id="generate-seeded">GENERATE FROM SEEDS</button></div>
  <div id="group-generator" class="ops-generator-row ops-generator-explained" ${structure!=='groups-playoffs'?'hidden':''}><label>Groups<span class="ops-field-help">Number of separate pools. Example: 2 creates Group A and Group B.</span><input id="group-count" type="number" min="1" max="8" value="${Number(rules.groupCount||2)}"></label><label>Qualify per group<span class="ops-field-help">Top teams from each group that enter playoffs.</span><input id="top-per-group" type="number" min="1" max="8" value="${Number(rules.topPerGroup||2)}"></label><label>Group BO<span class="ops-field-help">Games used to decide one group match.</span><select id="group-bo">${[1,3,5].map(v=>`<option value="${v}" ${Number(rules.groupBestOf||1)===v?'selected':''}>BO${v}</option>`).join('')}</select></label><label class="ops-check ops-check-explained"><input id="double-round-robin" type="checkbox" ${rules.doubleRoundRobin?'checked':''}><span><b>Double round robin</b><small>Every pair of teams plays twice instead of once.</small></span></label><button class="btn btn-primary btn-sm" id="generate-groups">GENERATE GROUPS</button></div>
  <div class="ops-bracket-quickbar"><span>Unfinished matches:</span>${[1,3,5].map(v=>`<button class="btn btn-ghost btn-sm apply-all-bo" data-bo="${v}">ALL BO${v}</button>`).join('')}<input id="bracket-search" placeholder="Search team" value="${escapeHtml(state.bracketSearch)}"><label class="ops-check"><input id="hide-completed" type="checkbox" ${state.hideCompleted?'checked':''}> Dim final</label><button class="btn btn-ghost btn-sm" id="zoom-out">−</button><button class="btn btn-ghost btn-sm" id="zoom-fit">FIT</button><button class="btn btn-ghost btn-sm" id="zoom-in">＋</button><button class="btn btn-ghost btn-sm" id="toggle-compact">${state.bracketCompact?'COMFORTABLE':'COMPACT'}</button><button class="btn btn-ghost btn-sm" id="bracket-fullscreen">FULLSCREEN</button></div>
  ${state.active.bracketSnapshots?.length?`<div class="ops-snapshot-row"><select id="snapshot-select">${state.active.bracketSnapshots.map(s=>`<option value="${s.id}">${escapeHtml(s.label)} · ${formatDate(s.created_at)}</option>`).join('')}</select><button class="btn btn-ghost btn-sm" id="restore-snapshot">RESTORE SNAPSHOT</button></div>`:''}</div>
  ${groupMatches.length?renderGroupStage(groupMatches,state.active.groupStandings||[],rules):''}
  ${playoffMatches.length?`<div class="ops-panel-header ops-playoff-heading"><div><h3>Playoff Bracket</h3><div class="ops-list-meta">Connected tree view · drag the background to move around.</div></div></div><div class="ops-bracket-viewport ${state.bracketCompact?'is-compact':''}" id="ops-bracket-viewport"><div class="ops-bracket-canvas" id="ops-bracket-canvas" style="--bracket-scale:${state.bracketZoom}"><svg class="ops-bracket-lines" id="ops-bracket-lines" aria-hidden="true"></svg>${rounds.map((round,index)=>{const ms=playoffMatches.filter(m=>m.round_no===round);const power=2**index;const offset=((power-1)*slot)/2;const gap=power*slot-cardHeight;return `<section class="ops-round" style="--round-offset:${offset}px;--round-gap:${gap}px;--match-height:${cardHeight}px"><div class="ops-round-header"><div class="ops-round-title">${escapeHtml(ms[0]?.round_name||`Round ${round}`)}</div><select class="round-bo" data-round="${round}">${[1,3,5,7].map(v=>`<option value="${v}" ${ms[0]?.best_of===v?'selected':''}>BO${v}</option>`).join('')}</select></div><div class="ops-round-matches">${ms.map(matchCard).join('')}</div></section>`;}).join('')}</div></div>`:(!groupMatches.length?'<div class="ops-empty" style="height:360px">No tournament structure generated.</div>':'')}`;
  if(isBroadcastViewer()){
    const controls=$('.ops-bracket-controls');
    controls?.querySelector('.ops-panel-header')?.replaceChildren(Object.assign(document.createElement('div'),{innerHTML:'<h3>BROADCASTER · VIEW ONLY</h3><div class="ops-list-meta">Open any match card to view the two teams and launch the read-only Broadcast overlay. Tournament controls are hidden.</div>'}));
    $('#bracket-structure')?.classList.add('hidden');$('#single-generator')?.remove();$('#group-generator')?.remove();$('#generate-playoffs')?.remove();$('.ops-bracket-guide')?.remove();$('.ops-snapshot-row')?.remove();$$('.apply-all-bo').forEach(button=>button.remove());$$('.round-bo').forEach(select=>{select.disabled=true;select.title='Broadcaster view only';});$$('.ops-bracket-team').forEach(button=>{button.disabled=true;button.title='Open the match card for Broadcast view';});
  }
  $('#bracket-structure').addEventListener('change',event=>{$('#single-generator').classList.toggle('hidden',event.target.value!=='single');$('#group-generator').classList.toggle('hidden',event.target.value!=='groups-playoffs');});$('#generate-seeded')?.addEventListener('click',()=>generateStructure('single'));$('#generate-groups')?.addEventListener('click',()=>generateStructure('groups'));$('#generate-playoffs')?.addEventListener('click',generatePlayoffs);$$('.apply-all-bo').forEach(btn=>btn.addEventListener('click',()=>applyBestOf(Number(btn.dataset.bo))));$$('.round-bo').forEach(select=>select.addEventListener('change',()=>applyBestOf(Number(select.value),Number(select.dataset.round))));$$('.ops-match-card').forEach(card=>card.addEventListener('click',()=>openMatchModal(Number(card.dataset.matchId))));$$('.ops-bracket-team').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();const teamId=Number(button.dataset.teamId);if(teamId)openTeamModal(teamId);}));$('#zoom-out')?.addEventListener('click',()=>setBracketZoom(state.bracketZoom-.1));$('#zoom-in')?.addEventListener('click',()=>setBracketZoom(state.bracketZoom+.1));$('#zoom-fit')?.addEventListener('click',fitBracket);$('#toggle-compact')?.addEventListener('click',()=>{state.bracketCompact=!state.bracketCompact;renderBracket();});$('#hide-completed')?.addEventListener('change',event=>{state.hideCompleted=event.target.checked;renderBracket();});$('#bracket-search')?.addEventListener('input',event=>{state.bracketSearch=event.target.value;const term=state.bracketSearch.trim().toLowerCase();$$('.ops-match-card').forEach(card=>{const hit=!term||card.textContent.toLowerCase().includes(term);card.classList.toggle('search-hit',Boolean(term&&hit));card.classList.toggle('search-dim',Boolean(term&&!hit));});});$('#bracket-fullscreen')?.addEventListener('click',()=>$('#ops-bracket-viewport')?.requestFullscreen());$('#restore-snapshot')?.addEventListener('click',restoreSnapshot);$$('.standing-override').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();manualStandingOverride(button);}));requestAnimationFrame(()=>{drawBracketConnectors();bindBracketPan();});
}
function drawBracketConnectors(){const canvas=$('#ops-bracket-canvas'),svg=$('#ops-bracket-lines');if(!canvas||!svg)return;const width=canvas.scrollWidth,height=canvas.scrollHeight;svg.setAttribute('width',width);svg.setAttribute('height',height);svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const paths=[];canvas.querySelectorAll('.ops-match-card[data-next-match-id]').forEach(source=>{const target=canvas.querySelector(`.ops-match-card[data-match-id="${source.dataset.nextMatchId}"]`);if(!target)return;const a=relativeRect(source,canvas),b=relativeRect(target,canvas);const x1=a.x+a.width,y1=a.y+a.height/2,x2=b.x,y2=b.y+b.height/2,mid=x1+Math.max(24,(x2-x1)/2);paths.push(`<path d="M ${x1} ${y1} H ${mid} V ${y2} H ${x2}"/>`);});svg.innerHTML=paths.join('');}
function relativeRect(element,ancestor){let x=0,y=0,node=element;while(node&&node!==ancestor){x+=node.offsetLeft;y+=node.offsetTop;node=node.offsetParent;}return{x,y,width:element.offsetWidth,height:element.offsetHeight};}
function bindBracketPan(){const viewport=$('#ops-bracket-viewport');if(!viewport)return;let active=false,startX=0,startY=0,left=0,top=0;const canPanVertically=()=>document.fullscreenElement===viewport;viewport.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('button,input,select,.ops-match-card'))return;active=true;viewport.setPointerCapture(event.pointerId);startX=event.clientX;startY=event.clientY;left=viewport.scrollLeft;top=viewport.scrollTop;viewport.classList.add('is-panning');});viewport.addEventListener('pointermove',event=>{if(!active)return;viewport.scrollLeft=left-(event.clientX-startX);if(canPanVertically())viewport.scrollTop=top-(event.clientY-startY);});const end=()=>{active=false;viewport.classList.remove('is-panning');};viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);viewport.addEventListener('wheel',event=>{if(event.shiftKey&&Math.abs(event.deltaY)>Math.abs(event.deltaX)){viewport.scrollLeft+=event.deltaY;event.preventDefault();}},{passive:false});}
function fitBracket(){const viewport=$('#ops-bracket-viewport'),canvas=$('#ops-bracket-canvas');if(!viewport||!canvas)return;const current=state.bracketZoom||1;const naturalWidth=canvas.offsetWidth||canvas.scrollWidth/current;const scale=Math.max(.5,Math.min(1.25,(viewport.clientWidth-32)/naturalWidth));setBracketZoom(scale);requestAnimationFrame(drawBracketConnectors);}

async function manualStandingOverride(button){const current=Number(button.dataset.rank);const rank=Number(prompt(`Override rank for this team (current #${current}):`,String(current)));if(!Number.isInteger(rank)||rank<1)return;const reason=prompt('Reason for manual standings override:');if(!reason)return;try{await api(`/api/tournaments/${state.activeId}/standings/override`,{method:'POST',body:{group:button.dataset.group,teamId:Number(button.dataset.team),rank,reason}});toast('Standing override saved with audit history.');await loadActiveTournament();}catch(error){toast(error.message,true);}}
function renderGroupStage(groupMatches,standings,rules){const groups=[...new Set(groupMatches.map(m=>m.group_name))].sort();const complete=standings.length&&standings.every(g=>g.complete);return `<section class="ops-group-stage-section"><div class="ops-panel-header ops-playoff-heading"><div><h3>Group Stage</h3><div class="ops-list-meta">${complete?'All group results are final. The playoff bracket can now be generated safely.':'Group matches are still in progress. Green-marked rows currently qualify.'} Tie-break order: ${escapeHtml((rules.tieBreakOrder||['wins','gameDiff','headToHead','gameWins','seed']).join(' → '))}</div></div><button class="btn btn-primary btn-sm" id="generate-playoffs" title="${complete?'Create playoffs from final standings':'Warning: creates playoffs from the current unfinished standings'}">${complete?'GENERATE PLAYOFFS':'GENERATE EARLY'}</button></div><div class="ops-group-grid">${groups.map(name=>{const ms=groupMatches.filter(m=>m.group_name===name);const table=standings.find(g=>g.group===name);return `<article class="ops-group-panel"><div class="ops-group-panel-heading"><h3>GROUP ${name}</h3><span>${ms.filter(m=>m.result_status==='final').length}/${ms.length} matches final</span></div><div class="ops-standing-table"><div class="ops-standing-row ops-standing-head"><b>#</b><span>TEAM</span><span>W–L</span><span>DIFF</span><span>ACTION</span></div>${table?.standings.map(row=>`<div class="ops-standing-row ${row.rank<=Number(rules.topPerGroup||2)?'qualifying':''}"><b>${row.rank}</b><span title="${escapeHtml(row.name||row.tag||'')}">${escapeHtml(row.tag||row.name)}${row.overrideActive?' ⚠':''}</span><span>${row.wins}-${row.losses}</span><span>${row.gameDiff>=0?'+':''}${row.gameDiff}</span>${can('bracket.generate')?`<button class="btn btn-ghost btn-xs standing-override" data-group="${name}" data-team="${row.teamId}" data-rank="${row.rank}">EDIT</button>`:'<span>—</span>'}</div>`).join('')||'<div class="ops-list-meta">No standings yet.</div>'}</div><div class="ops-group-match-help">Click a match card below to open Match Operations.</div><div class="ops-group-matches">${ms.map(matchCard).join('')}</div></article>`;}).join('')}</div></section>`;}
function matchCard(match){
  const term=state.bracketSearch.trim().toLowerCase();
  const text=`${match.team_a_name||''} ${match.team_b_name||''} ${match.team_a_tag||''} ${match.team_b_tag||''}`.toLowerCase();
  const highlight=Boolean(term&&text.includes(term));
  const searchDim=Boolean(term&&!highlight);
  const completedDim=state.hideCompleted&&match.result_status==='final';
  const resultState=match.result_status==='final'?'final':['disputed','under_review','recommended'].includes(match.result_status)?'dispute':match.result_status==='awaiting_confirmation'?'verify':'open';
  const resultText=resultState==='final'?'FINAL':resultState==='dispute'?'DISPUTE':resultState==='verify'?'VERIFY':'OPEN';
  const teamRow=(side)=>{
    const id=side==='a'?match.team_a_id:match.team_b_id;
    const name=side==='a'?match.team_a_name:match.team_b_name;
    const tag=side==='a'?match.team_a_tag:match.team_b_tag;
    const score=side==='a'?match.score_a:match.score_b;
    const winner=Boolean(id&&Number(match.winner_team_id)===Number(id));
    const loser=Boolean(id&&match.result_status==='final'&&!winner);
    const outcome=winner?'WIN':loser?'OUT':'';
    return `<button type="button" class="ops-bracket-team side-${side} ${winner?'winner':''} ${loser?'loser':''} ${!id?'is-tbd':''}" data-team-id="${id||''}" ${id?'title="Open team details"':'disabled'}><span class="ops-bracket-team-tag">${escapeHtml(tag||'—')}</span><span class="ops-bracket-team-name">${escapeHtml(name||'TBD')}</span><span class="ops-bracket-outcome">${outcome}</span><b>${score??'—'}</b></button>`;
  };
  return `<article class="ops-match-card result-${resultState} ${highlight?'search-hit':''} ${searchDim?'search-dim':''} ${completedDim?'completed-dim':''}" data-match-id="${match.id}" ${match.feeds_into_winner_match_id?`data-next-match-id="${match.feeds_into_winner_match_id}"`:''} aria-label="${escapeHtml(`${match.team_a_name||'TBD'} versus ${match.team_b_name||'TBD'}`)}" tabindex="0"><div class="ops-match-id"><span>#${match.position} · ${escapeHtml(statusLabel(match.match_status))}</span><span class="ops-match-state-wrap"><span class="ops-match-state state-${resultState}">${resultText}</span>${match.unread_count?`<span class="ops-unread" data-unread-match="${match.id}">${match.unread_count}</span>`:''}</span></div>${teamRow('a')}<div class="ops-match-versus" aria-hidden="true"><span></span><b>VS</b><span></span></div>${teamRow('b')}<div class="ops-match-footer"><span>BO${match.best_of} · ${escapeHtml(statusLabel(match.result_status))}</span><span class="ops-match-open-hint">OPEN MATCH</span><span class="ops-match-footer-right"><span>${escapeHtml(match.server_region||'')}</span>${match.stream_url?'<span class="ops-live-badge">LIVE ↗</span>':''}</span></div></article>`;
}

async function generateStructure(type,allowWarnings=false){if(!allowWarnings&&!confirm('Generate a new structure? A snapshot of the current bracket will be saved first.'))return;const url=type==='single'?`/api/tournaments/${state.activeId}/bracket/generate`:`/api/tournaments/${state.activeId}/bracket/generate-groups`;const body=type==='single'?{bestOf:Number($('#bracket-bo').value),allowWarnings}:{groupCount:Number($('#group-count').value),topPerGroup:Number($('#top-per-group').value),bestOf:Number($('#group-bo').value),doubleRoundRobin:$('#double-round-robin').checked,allowWarnings};try{await api(url,{method:'POST',body});toast(type==='single'?'Bracket generated.':'Group Stage generated.');await loadActiveTournament();}catch(error){if(error.message.includes('Constraint warnings require confirmation')&&!allowWarnings&&confirm(`${error.message}\n\nContinue anyway?`))return generateStructure(type,true);toast(error.message,true);}}
async function generatePlayoffs(){const incomplete=(state.active.groupStandings||[]).some(g=>!g.complete);if(incomplete&&!confirm('Some group results are not final. Generate playoffs from current standings?'))return;try{await api(`/api/tournaments/${state.activeId}/bracket/generate-playoffs`,{method:'POST',body:{topPerGroup:Number(state.active.tournament.rules.topPerGroup||2),bestOf:Number(state.active.tournament.rules.playoffBestOf||3),force:incomplete}});toast('Playoffs generated.');await loadActiveTournament();}catch(error){toast(error.message,true);}}
async function applyBestOf(bestOf,roundNo=null){try{await api(`/api/tournaments/${state.activeId}/matches/apply-best-of`,{method:'POST',body:{bestOf,roundNo}});toast(roundNo?`Round changed to BO${bestOf}.`:`All unfinished matches changed to BO${bestOf}.`);await loadActiveTournament();}catch(error){toast(error.message,true);}}
function setBracketZoom(value){state.bracketZoom=Math.max(.5,Math.min(1.5,Math.round(value*100)/100));$('#ops-bracket-canvas')?.style.setProperty('--bracket-scale',state.bracketZoom);requestAnimationFrame(drawBracketConnectors);}
async function restoreSnapshot(){const id=Number($('#snapshot-select').value);if(!confirm('Restore this snapshot? Current unstarted bracket data will be replaced.'))return;try{await api(`/api/tournaments/${state.activeId}/bracket/restore/${id}`,{method:'POST'});toast('Bracket snapshot restored.');await loadActiveTournament();}catch(error){toast(error.message,true);}}

function closeMatchModal(){state.openMatchId=null;$('#match-modal').classList.add('hidden');$('#match-modal-body').innerHTML='';}
async function openMatchModal(matchId){const match=state.active.matches.find(item=>item.id===matchId);if(!match)return;state.openMatchId=matchId;$('#match-modal').classList.remove('hidden');$('#match-modal-round').textContent=`${match.round_name} · Match #${match.position}`;$('#match-modal-title').textContent=`${match.team_a_name||'TBD'} vs ${match.team_b_name||'TBD'}`;$('#match-modal-body').innerHTML='<div class="ops-empty" style="height:280px">Loading match operations…</div>';try{const [resultData,checkins,gameData]=await Promise.all([api(`/api/matches/${match.id}/results`),api(`/api/matches/${match.id}/checkin`),api(`/api/matches/${match.id}/games`)]);renderMatchModal(match,resultData,checkins.checkins,gameData);}catch(error){$('#match-modal-body').innerHTML=`<div class="ops-empty" style="height:280px">${escapeHtml(error.message)}</div>`;}}
function renderBroadcastMatchModal(match,gameData){
  $('#match-modal-body').innerHTML=`<section class="ops-broadcast-match-view"><span class="ops-role-pill">BROADCASTER · VIEW ONLY</span><div class="ops-broadcast-versus"><article><span>BLUE TEAM</span><strong>${escapeHtml(match.team_a_name||'TBD')}</strong><small>${escapeHtml(match.team_a_tag||'')}</small></article><b>VS</b><article><span>RED TEAM</span><strong>${escapeHtml(match.team_b_name||'TBD')}</strong><small>${escapeHtml(match.team_b_tag||'')}</small></article></div><div class="ops-broadcast-match-facts"><span>BO${Number(match.best_of||1)}</span><span>${escapeHtml(statusLabel(match.series_rule||'normal'))}</span><span>${escapeHtml(statusLabel(match.match_status))}</span><span>${escapeHtml(formatDate(match.effective_scheduled_at))}</span><span>Game ${Number(gameData.currentGameNumber||match.current_game_number||1)}</span></div><div class="ops-result-warning">This account can view either team and the live Draft state, but cannot change the bracket, Draft, chat or result.</div><div class="ops-toolbar">${match.draft_room_ready?'<button class="btn btn-primary" id="open-broadcast-overlay">OPEN READ-ONLY BROADCAST VIEW</button>':'<button class="btn btn-ghost" disabled>WAITING FOR HOST TO OPEN DRAFT ROOM</button>'}</div></section>`;
  $('#open-broadcast-overlay')?.addEventListener('click',async()=>{try{const payload=await api(`/api/matches/${match.id}/draft-room/access`);openExternal(payload.url);}catch(error){toast(error.message,true);}});
}
function renderMatchModal(match,resultData,checkins,gameData){
  if(isBroadcastViewer()){renderBroadcastMatchModal(match,gameData);return;}
  const staff=state.active.staff||[];
  const refereeOptions=staff.filter(item=>['referee','host'].includes(item.role));
  const broadcasterOptions=staff.filter(item=>item.role==='broadcaster');
  const staffOptions=(items,selectedId)=>`<option value="">Unassigned</option>${items.map(item=>`<option value="${item.user_id}" ${Number(selectedId)===Number(item.user_id)?'selected':''}>${escapeHtml(item.display_name||item.username)} · ${escapeHtml(statusLabel(item.role))}</option>`).join('')}`;
  $('#match-modal-body').innerHTML=`<div class="ops-match-modal-grid"><section class="ops-match-settings"><div class="ops-fixed-start"><b>Effective start</b><span>${escapeHtml(formatDate(match.effective_scheduled_at))}</span><small>Fixed Tournament Start is active; nullable per-match scheduling fields are reserved for future scheduling modes.</small></div><div class="ops-settings-grid"><label>Best of<select id="modal-best-of">${[1,3,5,7].map(v=>`<option value="${v}" ${match.best_of===v?'selected':''}>BO${v}</option>`).join('')}</select></label><label>Series Rule<select id="modal-series-rule"><option value="normal" ${match.series_rule==='normal'?'selected':''}>Normal</option><option value="team_no_repeat" ${match.series_rule==='team_no_repeat'?'selected':''}>Team No Repeat — your team blocks its own earlier picks</option><option value="fearless" ${match.series_rule==='fearless'?'selected':''}>Fearless — either team’s earlier picks are blocked for both</option></select></label><label>Match Status<select id="modal-status">${['available','checkin_open','ready','drafting','playing','paused','technical_issue','completed','rescheduled','cancelled'].map(v=>`<option value="${v}" ${match.match_status===v?'selected':''}>${statusLabel(v)}</option>`).join('')}</select></label><label>Estimated duration (minutes)<input id="modal-duration" type="number" min="1" value="${escapeHtml(match.estimated_duration_minutes||'')}"></label><label>Server<input id="modal-server" value="${escapeHtml(match.server_region||'')}"></label><label>Station / setup<input id="modal-station" value="${escapeHtml(match.station_id||'')}" placeholder="Example: Station A"></label><label>Assigned Referee<select id="modal-referee">${staffOptions(refereeOptions,match.assigned_referee_id)}</select></label><label>Assigned Broadcaster<select id="modal-broadcaster">${staffOptions(broadcasterOptions,match.assigned_broadcaster_id)}</select></label><label>Game room code<input id="modal-room-code" value="${escapeHtml(match.room_code||'')}"></label><label>Team Blue logo URL<input id="modal-team-a-logo" type="url" value="${escapeHtml(match.team_a_logo||'')}" placeholder="Optional https://…"></label><label>Team Red logo URL<input id="modal-team-b-logo" type="url" value="${escapeHtml(match.team_b_logo||'')}" placeholder="Optional https://…"></label><label>Stream platform<select id="modal-stream-platform"><option value="">None</option>${['Twitch','YouTube','Kick','Bilibili'].map(v=>`<option value="${v}" ${match.stream_platform===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="ops-span-2">External stream URL<input id="modal-stream-url" value="${escapeHtml(match.stream_url||'')}" placeholder="Opens on Twitch / YouTube; never embedded"></label><label class="ops-span-2">Public notes<textarea id="modal-public-notes" rows="2">${escapeHtml(match.public_notes||'')}</textarea></label><label class="ops-span-2">Private staff notes<textarea id="modal-private-notes" rows="2">${escapeHtml(match.private_notes||'')}</textarea></label></div><div class="ops-toolbar ops-modal-actions"><button class="btn btn-primary btn-sm" id="modal-save-match">SAVE MATCH</button>${match.stream_url?'<button class="btn btn-ghost btn-sm" id="modal-open-stream">OPEN EXTERNAL STREAM ↗</button>':''}${match.team_a_id&&match.team_b_id?'<button class="btn btn-primary btn-sm" id="modal-draft-room">CREATE / OPEN DRAFT ROOM</button>':''}</div><div class="ops-checkin-row">${['team_a','team_b'].map(type=>`<button class="btn btn-ghost btn-xs modal-checkin" data-type="${type}">${checkins.some(c=>c.actor_type===type||c.actor_id===String(type==='team_a'?match.team_a_id:type==='team_b'?match.team_b_id:''))?'✓ ':''}${statusLabel(type)} READY</button>`).join('')}</div><div class="ops-link-grid" id="modal-draft-links"></div>${renderSeriesGamePanel(match,gameData)}${renderResultPanel(match,resultData)}</section><section class="ops-match-chat-panel"><div class="ops-chat-header"><div><b>MATCH CHAT</b><small>Host, Captains, permitted players and assigned referee.</small></div><button class="btn btn-ghost btn-xs" id="refresh-match-chat">↻</button></div><div class="ops-chat-messages" id="match-chat-messages"><div class="ops-list-meta">Loading messages…</div></div><form class="ops-chat-compose" id="match-chat-form"><input id="match-chat-input" maxlength="1000" placeholder="Write a message…"><input id="match-chat-file" type="file" accept="image/*,.pdf,.txt"><button class="btn btn-primary btn-sm">SEND</button></form></section></div>`;
  $('#modal-save-match').addEventListener('click',async()=>{try{await api(`/api/matches/${match.id}`,{method:'PATCH',body:{bestOf:Number($('#modal-best-of').value),seriesRule:$('#modal-series-rule').value,matchStatus:$('#modal-status').value,estimatedDurationMinutes:$('#modal-duration').value?Number($('#modal-duration').value):null,serverRegion:$('#modal-server').value,stationId:$('#modal-station').value||null,assignedRefereeId:$('#modal-referee').value?Number($('#modal-referee').value):null,assignedBroadcasterId:$('#modal-broadcaster').value?Number($('#modal-broadcaster').value):null,roomCode:$('#modal-room-code').value,teamALogoUrl:$('#modal-team-a-logo').value,teamBLogoUrl:$('#modal-team-b-logo').value,streamPlatform:$('#modal-stream-platform').value,streamUrl:$('#modal-stream-url').value,publicNotes:$('#modal-public-notes').value,privateNotes:$('#modal-private-notes').value}});toast('Match settings saved.');await loadActiveTournament();openMatchModal(match.id);}catch(error){toast(error.message,true);}});$('#modal-open-stream')?.addEventListener('click',()=>openExternal(match.stream_url));$('#modal-draft-room')?.addEventListener('click',()=>openDraftRoom(match.id));$$('.ops-record-game-winner').forEach(button=>button.addEventListener('click',()=>recordGameWinnerFromOps(match.id,button.dataset.side)));$$('.modal-checkin').forEach(btn=>btn.addEventListener('click',()=>checkIn(match,btn.dataset.type)));bindResultPanel(match,resultData);$('#refresh-match-chat').addEventListener('click',()=>loadMatchChat(match.id));$('#match-chat-form').addEventListener('submit',event=>sendChat(event,match.id));loadMatchChat(match.id);
  if(state.user?.role!=='admin')$$('.ops-record-game-winner').forEach(button=>{button.disabled=true;const hint=button.querySelector('em');if(hint)hint.textContent=t('viewOnly');});
  const seriesRuleSelect = $('#modal-series-rule');
  if (seriesRuleSelect && !seriesRuleSelect.querySelector('[value="squadra_blast"]')) {
    seriesRuleSelect.insertAdjacentHTML('beforeend', `<option value="squadra_blast">${escapeHtml(t('squadraBlastOption'))}</option>`);
    seriesRuleSelect.value = match.series_rule || 'normal';
  }
  if (match.series_rule === 'squadra_blast') {
    const ruleHelp = $('#match-modal-body .ops-series-heading small');
    if (ruleHelp) ruleHelp.textContent = t('squadraBlastPanel');
  }
}
function renderResultReconfirmation(match,current){
  if(!can('result.verify')||!current)return'';
  return `<details class="ops-correction-box ops-reconfirm-box"><summary>REQUEST BOTH TEAMS TO APPROVE AGAIN</summary><form id="result-reconfirm-form" class="ops-result-form"><label>${escapeHtml(match.team_a_name)} score<input id="reconfirm-score-a" type="number" min="0" value="${current.score_a??match.score_a??0}" required></label><label>${escapeHtml(match.team_b_name)} score<input id="reconfirm-score-b" type="number" min="0" value="${current.score_b??match.score_b??0}" required></label><label class="ops-span-2">Required review reason<input id="reconfirm-reason" required placeholder="Example: Score was wrong or a Captain approved by mistake"></label><div class="ops-result-warning ops-span-2">The current advancement is rolled back when safe. Both Captains must approve this reviewed score before the winner advances again.</div><button class="btn btn-danger btn-sm ops-span-2">RETURN RESULT TO BOTH CAPTAINS</button></form></details>`;
}
function renderResultPanel(match,data){
  const current=data.currentSubmission;
  const disputed=['disputed','under_review','recommended'].includes(match.result_status);
  const confirmations=Array.isArray(data.confirmations)?data.confirmations:[];
  const confirmationFor=teamId=>confirmations.find(item=>Number(item.team_id)===Number(teamId));
  const confirmationCard=(teamId,teamName)=>{
    const item=confirmationFor(teamId);
    const state=item?.decision==='confirm'?'confirmed':item?.decision==='reject'?'rejected':'pending';
    const label=state==='confirmed'?'CONFIRMED':state==='rejected'?'REJECTED':'PENDING';
    return `<div class="ops-verification-team ${state}"><span>${escapeHtml(teamName||'TBD')}</span><b>${label}</b><small>${item?.confirmed_by_name?`By ${escapeHtml(item.confirmed_by_name)}`:'Captain action required'}</small></div>`;
  };
  const history=`<details class="ops-result-history"><summary>Submission history (${data.submissions.length})</summary>${data.submissions.map(item=>`<div class="ops-history-row"><b>R${item.revision}</b><span>${item.score_a}-${item.score_b}</span><span>${escapeHtml(item.submitted_by_team_name||item.submitted_by_name||item.source_type)}</span><span>${formatDate(item.created_at)}</span></div>`).join('')||'<div class="ops-list-meta">No submissions yet.</div>'}</details>`;
  const winnerName=Number(match.winner_team_id)===Number(match.team_a_id)?match.team_a_name:Number(match.winner_team_id)===Number(match.team_b_id)?match.team_b_name:'Winner';
  if(match.result_status==='final') return `<div class="ops-result-panel"><div class="ops-panel-header ops-section-header"><div><h3>Final Result</h3><div class="ops-list-meta">The verified winner has advanced. The Host may return it to both Captains when a score or approval was incorrect.</div></div><span class="ops-result-lock">LOCKED</span></div><div class="ops-final-winner"><span>WINNER & ADVANCED</span><strong>${escapeHtml(winnerName)}</strong><div>${escapeHtml(match.team_a_name)} <b>${match.score_a}</b> – <b>${match.score_b}</b> ${escapeHtml(match.team_b_name)}</div><small>${escapeHtml(statusLabel(match.resolution_type||'normal'))}</small></div>${can('result.verify')?`<div class="ops-result-admin-actions">${renderResultReconfirmation(match,current)}<details class="ops-correction-box"><summary>UNDO FINAL RESULT</summary><form id="result-reopen-form" class="ops-result-form"><label class="ops-span-2">Required reason<input id="reopen-reason" required placeholder="Example: Wrong winner was confirmed"></label><div class="ops-result-warning ops-span-2">This removes the winner from the next round and returns this match to a reopened state. It is blocked after the dependent match starts.</div><button class="btn btn-danger btn-sm ops-span-2">UNDO RESULT & REMOVE ADVANCEMENT</button></form></details><details class="ops-correction-box"><summary>REOPEN & SUBMIT CORRECTION</summary><form id="result-correct-form" class="ops-result-form"><label>${escapeHtml(match.team_a_name)} score<input id="correct-score-a" type="number" min="0" value="${match.score_a}" required></label><label>${escapeHtml(match.team_b_name)} score<input id="correct-score-b" type="number" min="0" value="${match.score_b}" required></label><label class="ops-span-2">Required reason<input id="correct-reason" required placeholder="Example: Host selected the wrong winner"></label><button class="btn btn-danger btn-sm ops-span-2">REOPEN & SUBMIT CORRECTION</button></form></details></div>`:''}${history}</div>`;
  const stepOne=current?'done':'active';
  const stepTwo=match.result_status==='awaiting_confirmation'?'active':disputed?'blocked':current?'waiting':'waiting';
  const stepThree=disputed?'blocked':'waiting';
  return `<div class="ops-result-panel"><div class="ops-panel-header ops-section-header"><div><h3>Verified Result Workflow</h3><div class="ops-list-meta">No team advances from a report alone. A result becomes final only after the required Captain approvals or an authorized dispute ruling.</div></div></div><div class="ops-result-flow"><div class="${stepOne}"><b>1</b><span>Submit score</span></div><i></i><div class="${stepTwo}"><b>2</b><span>Captain approval</span></div><i></i><div class="${stepThree}"><b>3</b><span>Finalize & advance</span></div></div>${current?`<div class="ops-current-result"><b>Revision ${current.revision}</b><span>${escapeHtml(match.team_a_name)} ${current.score_a} – ${current.score_b} ${escapeHtml(match.team_b_name)}</span><small>Proposed winner: ${escapeHtml(Number(current.winner_team_id)===Number(match.team_a_id)?match.team_a_name:match.team_b_name)} · not advanced yet</small></div><div class="ops-verification-grid">${confirmationCard(match.team_a_id,match.team_a_name)}${confirmationCard(match.team_b_id,match.team_b_name)}</div>${renderResultReconfirmation(match,current)}`:''}${!disputed?`<form id="result-submit-form" class="ops-result-form"><label>${escapeHtml(match.team_a_name||'Team A')} score<input id="result-score-a" type="number" min="0" value="${current?.score_a??''}" required></label><label>${escapeHtml(match.team_b_name||'Team B')} score<input id="result-score-b" type="number" min="0" value="${current?.score_b??''}" required></label><label class="ops-span-2">Note<input id="result-note" placeholder="Optional result note"></label><div class="ops-result-warning ops-span-2">A Host report requires approval from both Captains. Conflicting team reports automatically open a dispute.</div><button class="btn btn-primary btn-sm ops-span-2">SUBMIT RESULT FOR APPROVAL</button></form>${data.requiredTeams?.length?`<div class="ops-awaiting-confirmation">Waiting for: ${data.requiredTeams.map(id=>id===match.team_a_id?match.team_a_name:match.team_b_name).join(', ')}</div>`:''}`:''}${data.dispute?`<div class="ops-dispute"><b>DISPUTE · ${escapeHtml(statusLabel(data.dispute.status))}</b><div>${escapeHtml(data.dispute.reason||'')}</div><form id="staff-evidence-form" class="ops-toolbar" style="margin-top:10px"><input id="staff-evidence-file" type="file" accept="image/*,.pdf,.txt" required><button class="btn btn-ghost btn-xs">UPLOAD STAFF EVIDENCE</button></form>${can('dispute.review')&&data.dispute.status==='open'?'<button class="btn btn-ghost btn-xs" id="dispute-review">START REVIEW</button>':''}${can('result.recommend')||can('result.verify')?`<details><summary>REFEREE RECOMMENDATION</summary><form id="dispute-recommend-form" class="ops-result-form"><label>${escapeHtml(match.team_a_name)} score<input id="recommend-score-a" type="number" min="0" required></label><label>${escapeHtml(match.team_b_name)} score<input id="recommend-score-b" type="number" min="0" required></label><label class="ops-span-2">Recommendation<input id="recommend-note" required></label><button class="btn btn-ghost btn-sm ops-span-2">SAVE RECOMMENDATION</button></form></details>`:''}${can('result.verify')?`<details><summary>FINAL ADMINISTRATIVE RULING</summary><form id="dispute-verify-form" class="ops-result-form"><label>${escapeHtml(match.team_a_name)} score<input id="verify-score-a" type="number" min="0" value="${data.dispute.recommended_score_a??''}" required></label><label>${escapeHtml(match.team_b_name)} score<input id="verify-score-b" type="number" min="0" value="${data.dispute.recommended_score_b??''}" required></label><label>Resolution<select id="verify-resolution"><option value="administrative_award">Administrative Award</option><option value="walkover">Walkover</option><option value="forfeit">Forfeit</option><option value="disqualification">Disqualification</option></select></label><label>Required reason<input id="verify-note" required></label><button class="btn btn-danger btn-sm ops-span-2">VERIFY & FINALIZE</button></form></details>`:''}</div>`:''}${history}</div>`;
}
function bindResultPanel(match,data){
  $('#result-reconfirm-form')?.addEventListener('submit',async event=>{event.preventDefault();const reason=$('#reconfirm-reason').value.trim();if(!reason||!confirm('Return this result to both Captains and require fresh approval?'))return;try{await api(`/api/matches/${match.id}/results/request-reconfirmation`,{method:'POST',body:{reason,scoreA:Number($('#reconfirm-score-a').value),scoreB:Number($('#reconfirm-score-b').value)}});toast('Result returned to both Captains for fresh approval.');await loadActiveTournament();openMatchModal(match.id);}catch(error){toast(error.message,true);}});
  $('#result-submit-form')?.addEventListener('submit',async event=>{event.preventDefault();try{const payload=await api(`/api/matches/${match.id}/results/submit`,{method:'POST',body:{sourceType:'host',scoreA:Number($('#result-score-a').value),scoreB:Number($('#result-score-b').value),note:$('#result-note').value}});toast(payload.autoFinalized?'Result finalized.':'Result submitted; both Captains must verify it before the winner advances.');await loadActiveTournament();openMatchModal(match.id);}catch(error){toast(error.message,true);}});
  $('#result-reopen-form')?.addEventListener('submit',async event=>{event.preventDefault();const reason=$('#reopen-reason').value.trim();if(!reason||!confirm('Undo this final result and remove the advanced winner from the next round?'))return;try{await api(`/api/matches/${match.id}/results/reopen`,{method:'POST',body:{reason}});toast('Final result undone. The advanced slot has been cleared.');await loadActiveTournament();openMatchModal(match.id);}catch(error){toast(error.message,true);}});
  $('#result-correct-form')?.addEventListener('submit',async event=>{event.preventDefault();try{await api(`/api/matches/${match.id}/results/correct`,{method:'POST',body:{reason:$('#correct-reason').value,scoreA:Number($('#correct-score-a').value),scoreB:Number($('#correct-score-b').value)}});toast('Correction submitted. Both Captains must confirm the new revision before anyone advances.');await loadActiveTournament();openMatchModal(match.id);}catch(error){toast(error.message,true);}});
  $('#dispute-review')?.addEventListener('click',async()=>{try{await api(`/api/matches/${match.id}/results/review`,{method:'POST',body:{note:'Review started from Host Dashboard'}});toast('Dispute moved to Under Review.');await loadActiveTournament();openMatchModal(match.id);}catch(error){toast(error.message,true);}});
  $('#staff-evidence-form')?.addEventListener('submit',async event=>{event.preventDefault();const file=$('#staff-evidence-file').files[0];if(!file)return;try{await api(`/api/matches/${match.id}/files`,{method:'POST',body:{purpose:'evidence',originalName:file.name,mimeType:file.type||'application/octet-stream',dataBase64:await readFileBase64(file)}});toast('Evidence uploaded as staff-only.');$('#staff-evidence-file').value='';}catch(error){toast(error.message,true);}});
  $('#dispute-recommend-form')?.addEventListener('submit',async event=>{event.preventDefault();try{await api(`/api/matches/${match.id}/results/recommend`,{method:'POST',body:{scoreA:Number($('#recommend-score-a').value),scoreB:Number($('#recommend-score-b').value),recommendation:$('#recommend-note').value}});toast('Referee recommendation saved.');await loadActiveTournament();openMatchModal(match.id);}catch(error){toast(error.message,true);}});
  $('#dispute-verify-form')?.addEventListener('submit',async event=>{event.preventDefault();try{await api(`/api/matches/${match.id}/results/verify`,{method:'POST',body:{scoreA:Number($('#verify-score-a').value),scoreB:Number($('#verify-score-b').value),resolutionNote:$('#verify-note').value,resolutionType:$('#verify-resolution').value}});toast('Administrative result finalized.');await loadActiveTournament();openMatchModal(match.id);}catch(error){toast(error.message,true);}});
}

async function checkIn(match,type){try{const actorId=type==='team_a'?match.team_a_id:type==='team_b'?match.team_b_id:type;await api(`/api/matches/${match.id}/checkin`,{method:'POST',body:{actorType:type.startsWith('team_')?'team':type,actorId}});toast('Check-in saved.');openMatchModal(match.id);}catch(error){toast(error.message,true);}}
async function openDraftRoom(matchId){try{const payload=await api(`/api/matches/${matchId}/draft-room`,{method:'POST'});const container=$('#modal-draft-links');container.innerHTML=Object.entries(payload.room.links).map(([role,url])=>`<div class="ops-link-row"><b>${escapeHtml(role)}</b><input readonly value="${escapeHtml(url)}"><a class="btn btn-ghost btn-xs" href="${escapeHtml(url)}" target="_blank" rel="noopener">OPEN</a><button class="btn btn-ghost btn-xs copy-draft-link" data-copy="${escapeHtml(url)}">COPY</button></div>`).join('');$$('.copy-draft-link').forEach(btn=>btn.addEventListener('click',()=>copyText(btn.dataset.copy,'Draft link copied.')));toast(`Draft Room ${payload.room.roomCode} ready.`);}catch(error){toast(error.message,true);}}
function renderSeriesGamePanel(match,gameData={}){const games=Array.isArray(gameData.games)?gameData.games:[],scoreA=Number(gameData.scoreA||0),scoreB=Number(gameData.scoreB||0),current=Number(gameData.currentGameNumber||match.current_game_number||1),canRecord=Boolean(gameData.draftComplete&&!gameData.seriesComplete),rule=String(gameData.seriesRule||match.series_rule||'normal');const gameRows=games.map(game=>{const winner=Number(game.winner_team_id)===Number(match.team_a_id)?match.team_a_name:Number(game.winner_team_id)===Number(match.team_b_id)?match.team_b_name:'Not recorded';return `<div class="ops-series-game-row"><span>GAME ${game.game_number}</span><b>${escapeHtml(statusLabel(game.status))}</b><em>${escapeHtml(winner)}</em></div>`;}).join('');return `<section class="ops-series-control"><div class="ops-series-heading"><div><h3>Series Game Control</h3><small>${rule==='fearless'?'Fearless: every hero used by either team locks for both teams. Example: once anyone uses Goku, nobody can use Goku again in this series.':rule==='team_no_repeat'?'Team No Repeat: each team loses only its own earlier picks. Example: if Team A used Goku, Team B may still use Goku.':'Normal: earlier picks may be reused.'}</small></div><span>GAME ${current} · ${escapeHtml(rule.replaceAll('_',' ').toUpperCase())}</span></div><div class="ops-series-score"><button type="button" class="ops-series-team team-a ops-record-game-winner" data-side="A" ${canRecord?'':'disabled'}><span>${escapeHtml(match.team_a_name||'Team A')}</span><strong>${scoreA}</strong><em>${canRecord?'WON CURRENT GAME':gameData.seriesComplete?'SERIES COMPLETE':'FINISH DRAFT FIRST'}</em></button><div class="ops-series-mid"><small>FIRST TO ${Number(gameData.winsNeeded||Math.floor(match.best_of/2)+1)}</small><b>VS</b></div><button type="button" class="ops-series-team team-b ops-record-game-winner" data-side="B" ${canRecord?'':'disabled'}><strong>${scoreB}</strong><span>${escapeHtml(match.team_b_name||'Team B')}</span><em>${canRecord?'WON CURRENT GAME':gameData.seriesComplete?'SERIES COMPLETE':'FINISH DRAFT FIRST'}</em></button></div><div class="ops-series-help">${gameData.seriesComplete?'The BO score is complete. Continue with the official result submission/confirmation below.':canRecord?'After the actual game ends, select the winner here. The next Draft Room game is created automatically.':'Complete the current ban/pick before recording a point.'}</div><div class="ops-series-history">${gameRows||'<div class="ops-list-meta">No completed draft games yet.</div>'}</div></section>`;}
async function recordGameWinnerFromOps(matchId,side){const match=state.active.matches.find(item=>item.id===matchId);const teamName=side==='A'?match?.team_a_name:match?.team_b_name;if(!confirm(`Record ${teamName||`Team ${side}`} as the current game winner?`))return;try{const payload=await api(`/api/matches/${matchId}/draft-room/game-result`,{method:'POST',body:{winnerSide:side}});toast(payload.seriesComplete?`Series score complete: ${payload.scoreA}-${payload.scoreB}.`:t('openingNextGameDraft',{game:payload.currentGameNumber}));if(payload.nextDraftUrl){window.location.assign(payload.nextDraftUrl);return;}await loadActiveTournament();openMatchModal(matchId);}catch(error){toast(error.message,true);}}
async function loadMatchChat(matchId){const container=$('#match-chat-messages');if(!container)return;try{const payload=await api(`/api/matches/${matchId}/messages`);container.innerHTML='';if(!payload.messages.length)container.innerHTML='<div class="ops-list-meta">No messages yet.</div>';payload.messages.forEach(appendChat);container.scrollTop=container.scrollHeight;const match=state.active.matches.find(m=>m.id===matchId);if(match)match.unread_count=0;updateUnreadBadge(matchId,0);}catch(error){container.innerHTML=`<div class="ops-list-meta">${escapeHtml(error.message)}</div>`;}}
function appendChat(message){const container=$('#match-chat-messages');if(!container||container.querySelector(`[data-message-id="${message.id}"]`))return;container.querySelector('.ops-list-meta')?.remove();const item=document.createElement('div');item.className=`ops-chat-message ${message.message_type==='system'?'system':''} ${message.pinned?'pinned':''}`;item.dataset.messageId=message.id;item.innerHTML=`<div class="ops-chat-message-head"><b>${escapeHtml(message.sender_name||message.sender_role||'Unknown')}</b><span>${formatDate(message.created_at)}${message.edited_at?' · edited':''}${message.pinned?' · PINNED':''}</span></div><div>${escapeHtml(message.deleted_at?'[deleted]':message.message||'')}</div>${chatAttachmentHtml(message)}`;container.appendChild(item);item.querySelector('.ops-file-link')?.addEventListener('click',event=>downloadFile(Number(event.currentTarget.dataset.fileId),event.currentTarget.dataset.fileName));container.scrollTop=container.scrollHeight;}
async function sendChat(event,matchId){event.preventDefault();const input=$('#match-chat-input'),fileInput=$('#match-chat-file');let fileId=null;try{if(fileInput.files[0]){const file=fileInput.files[0];const dataBase64=await readFileBase64(file);const uploaded=await api(`/api/matches/${matchId}/files`,{method:'POST',body:{purpose:'chat_attachment',originalName:file.name,mimeType:file.type||'application/octet-stream',dataBase64}});fileId=uploaded.file.id;}const message=input.value.trim();if(!message&&!fileId)return;await api(`/api/matches/${matchId}/messages`,{method:'POST',body:{message,fileId}});input.value='';fileInput.value='';}catch(error){toast(error.message,true);}}
function readFileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});}
function updateUnreadBadge(matchId,count=null){const match=state.active?.matches.find(m=>m.id===matchId);if(match&&count===null)match.unread_count=(match.unread_count||0)+1;else if(match)match.unread_count=count;const badge=document.querySelector(`[data-unread-match="${matchId}"]`);if(badge)badge.textContent=match?.unread_count||'';}

function renderRules() {
  const tournament = state.active.tournament;
  const rules = tournament.rules || {};
  const panel = $('#tab-rules');
  panel.innerHTML = `
    <div class="ops-section">
      <h3>Tournament Information, Fixed Start & Retention</h3>
      <form id="tournament-settings-form" class="ops-settings-grid">
        <label>Name<input id="rule-name" value="${escapeHtml(tournament.name)}" required></label>
        <label>Status<select id="rule-status">${['preparing','ongoing','paused','completed','cancelled','archived'].map(value => `<option value="${value}" ${tournament.status === value ? 'selected' : ''}>${value}</option>`).join('')}</select></label>
        <label>Tournament start<input id="rule-start-at" type="datetime-local" value="${tournament.start_at ? escapeHtml(tournament.start_at.slice(0,16)) : ''}"></label>
        <label>Timezone<input id="rule-timezone" value="${escapeHtml(tournament.timezone)}"></label>
        <label>Roster lock deadline<input id="rule-roster-lock" type="datetime-local" value="${tournament.roster_lock_at ? escapeHtml(tournament.roster_lock_at.slice(0,16)) : ''}"></label>
        <label>Result reopen window (hours)<input id="rule-reopen-hours" type="number" min="1" max="168" value="${Number(tournament.result_reopen_hours || 24)}"></label>
        <label>Evidence retention after Tournament Final<input id="rule-evidence-days" type="number" min="1" value="${Number(tournament.evidence_retention_days || 90)}"></label>
        <label>Chat attachment retention<input id="rule-chat-days" type="number" min="1" value="${Number(tournament.chat_retention_days || 30)}"></label>
        <label>Default server<input id="rule-server" value="${escapeHtml(tournament.default_server)}"></label>
        <label>Stream platform<select id="rule-stream-platform"><option value="">None</option>${['Twitch','YouTube','Kick','Bilibili'].map(value => `<option value="${value}" ${tournament.public_stream_platform === value ? 'selected' : ''}>${value}</option>`).join('')}</select></label>
        <label class="ops-span-2">External official stream URL<input id="rule-stream-url" value="${escapeHtml(tournament.public_stream_url || '')}" placeholder="Opens on the external platform"></label>
        <label class="ops-span-2">${escapeHtml(t('discordInviteField'))}<input id="rule-discord-url" type="url" value="${escapeHtml(tournament.discord_url || '')}" placeholder="https://discord.gg/..."></label>
        <label>Stream label<input id="rule-stream-label" value="${escapeHtml(tournament.public_stream_label || '')}"></label>
        <label class="ops-span-2">Description<textarea id="rule-description" rows="3">${escapeHtml(tournament.description)}</textarea></label>
        <div class="ops-span-2 ops-toolbar"><span class="ops-list-meta">Visibility: <b>${tournament.is_public ? 'PUBLIC' : 'PRIVATE / DRAFT'}</b></span><button type="button" class="btn ${tournament.is_public ? 'btn-danger' : 'btn-ghost'}" id="toggle-tournament-public">${tournament.is_public ? 'UNPUBLISH' : 'PUBLISH'}</button><button class="btn btn-primary">SAVE TOURNAMENT INFO</button></div>
      </form>
      <div class="ops-list-meta">Fixed Tournament Start is enabled in the UI. Nullable per-stage and per-match scheduling fields already exist for future upgrades.</div>
    </div>
    <div class="ops-section">
      <h3>Stage, Series & Tie-break Defaults</h3>
      <form id="format-rules-form" class="ops-settings-grid">
        <label>Group default<select id="rule-group-bo">${[1,3,5].map(value => `<option value="${value}" ${Number(rules.groupBestOf || 1) === value ? 'selected' : ''}>BO${value}</option>`).join('')}</select></label>
        <label>Playoff default<select id="rule-playoff-bo">${[1,3,5,7].map(value => `<option value="${value}" ${Number(rules.playoffBestOf || 3) === value ? 'selected' : ''}>BO${value}</option>`).join('')}</select></label>
        <label>Grand Final<select id="rule-final-bo">${[3,5,7].map(value => `<option value="${value}" ${Number(rules.grandFinalBestOf || 5) === value ? 'selected' : ''}>BO${value}</option>`).join('')}</select></label>
        <label>Default series rule<select id="rule-series"><option value="normal" ${rules.seriesRule === 'normal' || !rules.seriesRule ? 'selected' : ''}>Normal</option><option value="team_no_repeat" ${rules.seriesRule === 'team_no_repeat' ? 'selected' : ''}>Team No Repeat — your team blocks its own earlier picks</option><option value="fearless" ${rules.seriesRule === 'fearless' ? 'selected' : ''}>Fearless — either team’s earlier picks block both teams</option><option value="squadra_blast" ${rules.seriesRule === 'squadra_blast' ? 'selected' : ''}>${escapeHtml(t('squadraBlastOption'))}</option></select></label>
        <label class="ops-span-2">Tie-break order<input id="rule-tiebreak" value="${escapeHtml((rules.tieBreakOrder || ['wins','gameDiff','headToHead','gameWins','seed']).join(','))}"></label>
        <div class="ops-span-2"><button class="btn btn-primary">SAVE FORMAT DEFAULTS</button></div>
      </form>
    </div>
    <div class="ops-section">
      <div class="ops-section-header"><div><h3>Default Draft Rules</h3><div class="ops-list-meta">The exact same rule component is used in Quick Draft and Tournament Operations.</div></div></div>
      ${renderDraftRulesForm(rules, { formId: 'draft-rules-form', submitLabel: 'SAVE DRAFT RULES' })}
    </div>`;

  $('#toggle-tournament-public').addEventListener('click', async () => {
    const publish = !Boolean(tournament.is_public);
    const message = publish
      ? 'Publish this tournament to the public listing and public bracket? Confirm that no private notes or room codes were entered into public fields.'
      : 'Unpublish this tournament immediately? Existing public links will stop returning it.';
    if (!confirm(message)) return;
    try {
      await api(`/api/tournaments/${state.activeId}/${publish ? 'publish' : 'unpublish'}`, { method: 'POST', body: { confirm: true } });
      toast(publish ? 'Tournament published.' : 'Tournament unpublished.');
      await loadActiveTournament();
    } catch (error) { toast(error.message, true); }
  });

  $('#tournament-settings-form').addEventListener('submit', async event => {
    event.preventDefault();
    try {
      await api(`/api/tournaments/${state.activeId}`, { method: 'PATCH', body: {
        name: $('#rule-name').value,
        status: $('#rule-status').value,
        startAt: $('#rule-start-at').value || null,
        timezone: $('#rule-timezone').value,
        rosterLockAt: $('#rule-roster-lock').value || null,
        resultReopenHours: Number($('#rule-reopen-hours').value),
        evidenceRetentionDays: Number($('#rule-evidence-days').value),
        chatRetentionDays: Number($('#rule-chat-days').value),
        defaultServer: $('#rule-server').value,
        publicStreamPlatform: $('#rule-stream-platform').value,
        publicStreamUrl: $('#rule-stream-url').value,
        publicStreamLabel: $('#rule-stream-label').value,
        discordUrl: $('#rule-discord-url').value,
        description: $('#rule-description').value,
      }});
      toast('Tournament settings saved.');
      await loadTournaments();
    } catch (error) { toast(error.message, true); }
  });

  $('#format-rules-form').addEventListener('submit', async event => {
    event.preventDefault();
    try {
      const tieBreakOrder = $('#rule-tiebreak').value.split(',').map(value => value.trim()).filter(Boolean);
      await api(`/api/tournaments/${state.activeId}`, { method: 'PATCH', body: { rules: {
        ...rules,
        groupBestOf: Number($('#rule-group-bo').value),
        playoffBestOf: Number($('#rule-playoff-bo').value),
        grandFinalBestOf: Number($('#rule-final-bo').value),
        seriesRule: $('#rule-series').value,
        tieBreakOrder,
      }}});
      toast('Format defaults saved.');
      await loadActiveTournament();
    } catch (error) { toast(error.message, true); }
  });

  bindDraftRulesForm($('#draft-rules-form'), {
    rules,
    onSubmit: async nextRules => {
      try {
        await api(`/api/tournaments/${state.activeId}`, { method: 'PATCH', body: { rules: { ...rules, ...nextRules } } });
        toast('Draft defaults and hero rules saved.');
        await loadActiveTournament();
      } catch (error) { toast(error.message, true); }
    },
  });
}
function renderStaff(){
  const panel=$('#tab-staff');
  if(!panel)return;
  const staff=state.active.staff||[];
  const roleDescriptions={
    host:'Tournament operations, teams, seeding, bracket, matches and final rulings.',
    referee:'Check-in, dispute review, evidence access, recommendations and draft pause.',
    scheduler:'Match scheduling, station assignment and operational match updates.',
    scorekeeper:'Submit match results without full host permissions.',
    broadcaster:'External stream links and OBS broadcast controls.'
  };
  const canManage=can('tournament.manage');
  panel.innerHTML=`<div class="ops-section"><div class="ops-panel-header ops-section-header"><div><h3>Staff & Permission Roles</h3><div class="ops-list-meta">Staff must register an account before the Host assigns a tournament role. Captains are managed from Teams & Seeding.</div></div></div>${canManage?`<form id="staff-assign-form" class="ops-form-card ops-staff-form"><label>Username<input id="staff-identity" required placeholder="Existing account"></label><label>Role<select id="staff-role">${Object.keys(roleDescriptions).map(role=>`<option value="${role}">${statusLabel(role)}</option>`).join('')}</select></label><button class="btn btn-primary" type="submit">ASSIGN STAFF</button></form>`:'<div class="ops-list-meta">You can view staff assignments, but only the Tournament Owner/Host can change them.</div>'}<div class="ops-staff-grid">${staff.length?staff.map(item=>`<article class="ops-staff-card"><div><b>${escapeHtml(item.display_name||item.username)}</b><div class="ops-list-meta">@${escapeHtml(item.username)}${item.email?` · ${escapeHtml(item.email)}`:''}</div></div><span class="ops-role-pill">${escapeHtml(statusLabel(item.role))}</span><p>${escapeHtml(roleDescriptions[item.role]||'Custom tournament staff role.')}</p>${item.permissions?.length?`<div class="ops-permission-tags">${item.permissions.map(permission=>`<code>${escapeHtml(permission)}</code>`).join('')}</div>`:''}${canManage?`<button class="btn btn-danger btn-xs remove-staff" data-user-id="${item.user_id}" data-role="${escapeHtml(item.role)}">REMOVE ROLE</button>`:''}</article>`).join(''):'<div class="ops-empty" style="height:180px">No additional tournament staff assigned.</div>'}</div></div><div class="ops-section"><h3>Permission Boundaries</h3><div class="ops-qol-list"><div><b>Host/Owner</b><span>Final operational authority and result.verify.</span></div><div><b>Referee</b><span>Only enters the result flow when a dispute or administrative ruling exists.</span></div><div><b>Broadcaster</b><span>Manages external stream links and OBS overlay; the website never embeds livestream video.</span></div><div><b>Public viewer</b><span>No account and no Spectator role. Public pages show only bracket-safe data.</span></div></div></div>`;
  $('#staff-assign-form')?.addEventListener('submit',async event=>{event.preventDefault();try{await api(`/api/tournaments/${state.activeId}/staff`,{method:'POST',body:{identity:$('#staff-identity').value.trim(),role:$('#staff-role').value}});toast('Staff role assigned.');await loadActiveTournament();}catch(error){toast(error.message,true);}});
  $$('.remove-staff').forEach(button=>button.addEventListener('click',async()=>{if(!confirm(`Remove the ${statusLabel(button.dataset.role)} role from this account?`))return;try{await api(`/api/tournaments/${state.activeId}/staff/${Number(button.dataset.userId)}/${encodeURIComponent(button.dataset.role)}`,{method:'DELETE'});toast('Staff role removed.');await loadActiveTournament();}catch(error){toast(error.message,true);}}));
}

function renderStartgg(){
  const t=state.active.tournament;
  const platform=String(t.source_platform||'manual');
  const label=platform==='startgg'?'start.gg':platform==='tonamel'?'Tonamel':platform==='challonge'?'Challonge':'Manual';
  const sourceUrl=t.source_url||t.startgg_url||'';
  const canSyncEntrants=platform==='startgg'&&Boolean(sourceUrl);
  $('#tab-startgg').innerHTML=`<div class="ops-section"><div class="ops-panel-header ops-section-header"><div><h3>External Tournament Source</h3><div class="ops-list-meta">This link establishes per-event ownership. It does not grant global Host access.</div></div><span class="ops-role-pill">${escapeHtml(label)}</span></div><div class="ops-qol-list"><div><b>Source URL</b><span>${sourceUrl?`<a href="${escapeHtml(sourceUrl)}" target="_blank" rel="noopener">${escapeHtml(sourceUrl)} ↗</a>`:'No external source is linked.'}</span></div><div><b>External ID</b><span>${escapeHtml(t.source_external_id||t.startgg_slug||'Not available')}</span></div><div><b>Link status</b><span>${escapeHtml(statusLabel(t.source_sync_status||'linked'))}</span></div><div><b>Last checked</b><span>${escapeHtml(formatDate(t.source_last_synced_at))}</span></div></div></div>${canSyncEntrants?`<div class="ops-section"><h3>Sync start.gg Entrants</h3><form id="startgg-form" class="ops-form-card" style="grid-template-columns:1fr auto"><label>start.gg tournament URL<input id="startgg-url" value="${escapeHtml(sourceUrl)}" readonly></label><button class="btn btn-primary">SYNC ENTRANTS</button></form><div class="ops-list-meta">Read-only roster import. Captain accounts still need to be linked on this website.</div></div>`:`<div class="ops-section"><h3>Registration Data</h3><div class="ops-list-meta">Automatic entrant sync is currently available for start.gg when its API token is configured. For ${escapeHtml(label)}, add teams manually or import them with a future provider connector.</div></div>`}`;
  $('#startgg-form')?.addEventListener('submit',async event=>{event.preventDefault();try{const payload=await api(`/api/tournaments/${state.activeId}/import-startgg`,{method:'POST',body:{url:sourceUrl}});toast(`Imported ${payload.teamCount} teams and ${payload.memberCount} roster entries. Captain accounts still need linking.`);await loadActiveTournament();}catch(error){toast(error.message,true);}});
}
async function renderAudit(){const panel=$('#tab-audit');if(!panel)return;panel.innerHTML='<div class="ops-section"><div class="ops-list-meta">Open this tab to load the latest audit activity.</div><button class="btn btn-primary btn-sm" id="load-audit">LOAD ACTIVITY</button></div>';$('#load-audit').addEventListener('click',async()=>{try{const payload=await api(`/api/tournaments/${state.activeId}/audit`);panel.innerHTML=`<div class="ops-section"><h3>Audit Activity</h3><div class="ops-audit-list">${payload.logs.map(log=>`<div class="ops-history-row"><b>${escapeHtml(log.action)}</b><span>${escapeHtml(log.user_name||'System')}</span><span>${formatDate(log.created_at)}</span><code>${escapeHtml(JSON.stringify(log.details))}</code></div>`).join('')}</div></div>`;}catch(error){toast(error.message,true);}});}


function closeDevConsole(){ $('#dev-console-modal').classList.add('hidden'); }
async function openDevConsole(){
  $('#dev-console-modal').classList.remove('hidden');
  const body=$('#dev-console-body');
  body.innerHTML='<div class="ops-loading">Loading test suites…</div>';
  try{const payload=await api('/api/dev-test/suites');renderDevConsole(payload.suites||[]);}catch(error){body.innerHTML=`<div class="ops-error">${escapeHtml(error.message)}</div>`;}
}
function devLink(url,label,variant='ghost'){
  if(!url)return '';
  return `<a class="btn btn-${variant} btn-xs" href="${escapeHtml(url)}" target="_blank" rel="noopener">${escapeHtml(label)}</a>`;
}
function renderDevConsole(suites){
  const body=$('#dev-console-body');
  body.innerHTML=`<section class="ops-dev-intro"><div><h3>Full Tournament Test Suite</h3><p>Create four isolated tournaments: registration/join review, manual bracket generation, live Captain check-in + Draft Room, and a completed championship for profile history.</p></div><button type="button" class="btn btn-primary" id="create-test-suite">CREATE TEST SUITE</button></section>
  <div class="ops-notice warning">Test records are clearly marked <b>TEST</b>. Use Cleanup to remove only the users and tournaments created by that suite.</div>
  <div class="ops-dev-suite-list">${suites.length?suites.map(renderDevSuite).join(''):'<div class="ops-empty">No test suites yet.</div>'}</div>`;
  $('#create-test-suite').addEventListener('click',createDevSuite);
  $$('.cleanup-test-suite').forEach(button=>button.addEventListener('click',()=>cleanupDevSuite(Number(button.dataset.suiteId))));
  $$('.copy-test-identity').forEach(button=>button.addEventListener('click',()=>copyText(button.dataset.value,'Test username copied.')));
}
function renderDevSuite(suite){
  const scenarios=Object.fromEntries((suite.tournaments||[]).map(item=>[item.scenario,item]));
  const mainUsers=(suite.users||[]).filter(user=>['host','applicant_player','applicant_captain','captain_1','captain_8','referee','broadcaster'].includes(user.persona));
  return `<article class="ops-dev-suite" data-suite-id="${suite.id}">
    <div class="ops-panel-header"><div><div class="ops-kicker">SUITE #${suite.id}</div><h3>${escapeHtml(suite.name)}</h3><div class="ops-list-meta">Created ${formatDate(suite.createdAt)} by ${escapeHtml(suite.createdBy)}</div></div><button type="button" class="btn btn-danger btn-sm cleanup-test-suite" data-suite-id="${suite.id}">CLEANUP</button></div>
    <div class="ops-dev-scenarios">
      <div><b>1 · Registration & Join</b><span>${escapeHtml(scenarios.registration?.status||'missing')}</span>${devLink(`/public.html?slug=${encodeURIComponent(scenarios.registration?.slug||'')}`,'PUBLIC')}${devLink(suite.quickLinks?.applicant,'JOIN AS PLAYER','primary')}</div>
      <div><b>2 · Generate Bracket</b><span>${escapeHtml(scenarios.bracket?.status||'missing')}</span>${devLink(suite.quickLinks?.bracketHost,'OPEN AS HOST','primary')}</div>
      <div><b>3 · Live Check-in</b><span>${escapeHtml(scenarios.live?.status||'missing')}</span>${devLink(suite.quickLinks?.host,'HOST DASHBOARD','primary')}${devLink(suite.quickLinks?.captainA,'CAPTAIN A')}${devLink(suite.quickLinks?.captainB,'CAPTAIN B')}</div>
      <div><b>4 · Completed History</b><span>${escapeHtml(scenarios.completed?.status||'missing')}</span>${devLink(`/public.html?slug=${encodeURIComponent(scenarios.completed?.slug||'')}`,'RESULTS')}</div>
    </div>
    <div class="ops-dev-view-links"><b>Host tools:</b>${devLink(suite.quickLinks?.hostImport,'CREATE / IMPORT EVENT')}<b>Multi-view:</b>${devLink(suite.quickLinks?.draftHost,'DRAFT HOST')}${devLink(suite.quickLinks?.draftTeamA,'TEAM BLUE')}${devLink(suite.quickLinks?.draftTeamB,'TEAM RED')}${devLink(suite.quickLinks?.referee,'REFEREE')}${devLink(suite.quickLinks?.broadcast,'OBS OVERLAY')}</div>
    <details class="ops-dev-accounts"><summary>Test accounts (${suite.users?.length||0})</summary><div class="ops-dev-account-grid">${mainUsers.map(user=>`<div class="ops-dev-account"><div><b>${escapeHtml(user.display_name)}</b><span>${escapeHtml(user.persona)} · ${escapeHtml(user.role)}</span><code>${escapeHtml(user.username)}</code></div><div>${devLink(user.accessUrl,'OPEN','primary')}<button type="button" class="btn btn-ghost btn-xs copy-test-identity" data-value="${escapeHtml(user.username)}">COPY USER</button></div></div>`).join('')}</div></details>
  </article>`;
}
async function createDevSuite(){
  const button=$('#create-test-suite');button.disabled=true;button.textContent='CREATING…';
  try{
    const result=await api('/api/dev-test/suites',{method:'POST'});
    const suite=result.suite;
    const modal=document.createElement('div');modal.className='ops-notice success';
    modal.innerHTML=`<b>Test suite created.</b> Shared password for every generated account: <code>${escapeHtml(result.password)}</code><br>Copy it now; for security it is not stored in readable form. One-click OPEN links do not require typing the password.`;
    $('#dev-console-body').prepend(modal);
    await loadTournaments();
    const payload=await api('/api/dev-test/suites');renderDevConsole(payload.suites||[]);
    $('#dev-console-body').prepend(modal);
    toast(`Created ${suite?.tournaments?.length||4} test tournaments.`);
  }catch(error){toast(error.message,true);button.disabled=false;button.textContent='CREATE TEST SUITE';}
}
async function cleanupDevSuite(suiteId){
  if(!confirm('Delete every test tournament and test account in this suite? Real tournament data will not be touched.'))return;
  try{await api(`/api/dev-test/suites/${suiteId}`,{method:'DELETE'});toast('Test suite cleaned up.');await loadTournaments();const payload=await api('/api/dev-test/suites');renderDevConsole(payload.suites||[]);}catch(error){toast(error.message,true);}
}


function bindGlobalErrorBoundary(){
  if(window.__gekishinErrorBoundaryBound)return;
  window.__gekishinErrorBoundaryBound=true;
  window.addEventListener('unhandledrejection',event=>{
    event.preventDefault();
    const message=event.reason?.message||'An unexpected operation failed.';
    console.error(event.reason);
    toast(message,true);
  });
  window.addEventListener('error',event=>{
    if(!event.error)return;
    console.error(event.error);
    toast(event.error.message||'An unexpected interface error occurred.',true);
  });
}

bindGlobalErrorBoundary();
bootstrap();
